package com.tsghub;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.tsghub.TsgHubUi.Tone;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.Consumer;
import java.util.function.Function;
import java.util.function.Supplier;
import javax.swing.SwingUtilities;

final class TsgHubAnnouncements
{
	static final int MAX_CHAT_LINES = 3;

	private final TsgHubPlugin plugin;
	private final ScheduledExecutorService executor;
	private final Supplier<TsgHubApi> api;
	private final Supplier<TsgHubNewsEditor> panel;
	private final Consumer<String> chat;
	private final TsgHubNewsPoll polls;
	private volatile JsonArray list;

	TsgHubAnnouncements(TsgHubPlugin plugin, ScheduledExecutorService executor, Supplier<TsgHubApi> api, Supplier<TsgHubNewsEditor> panel, Consumer<String> chat)
	{
		this.plugin = plugin;
		this.executor = executor;
		this.api = api;
		this.panel = panel;
		this.chat = chat;
		this.polls = new TsgHubNewsPoll(plugin, this, () -> plugin.newsWindow(TsgHubNewsWindow::render));
	}

	TsgHubNewsPoll polls()
	{
		return polls;
	}

	JsonArray list()
	{
		return list;
	}

	void load()
	{
		if (!plugin.canUseHub() || executor.isShutdown()) return;
		String clan = TsgHubApi.encode(plugin.getDetectedClanName());
		String token = plugin.adminKey();
		String hash = plugin.accountHash();
		String query = "/v1/announcements?clanName=" + clan + (hash.isEmpty() ? "" : "&accountHash=" + hash);
		api.get().call("GET", query, token.isEmpty() ? null : token, null)
			.thenAcceptAsync(result -> apply(TsgHubJson.array(result, "announcements")), executor);
	}

	void apply(JsonArray all)
	{
		if (!plugin.canUseHub()) return;
		JsonArray announcements = published(all);
		list = announcements;
		SwingUtilities.invokeLater(() -> polls.reset(announcements));
		plugin.ui(s -> s.setAnnouncements(announcements));
		plugin.newsWindow(w -> w.setAnnouncements(announcements));
		SwingUtilities.invokeLater(() -> {
			TsgHubNewsEditor admin = panel.get();
			if (admin != null) admin.setAnnouncements(all);
		});
		alert(announcements);
	}

	static JsonArray published(JsonArray all)
	{
		JsonArray out = new JsonArray();
		for (JsonObject announcement : TsgHubJson.objects(all))
			if (!TsgHubJson.bool(announcement, "draft") && !TsgHubJson.bool(announcement, "expired")) out.add(announcement);
		return out;
	}

	private synchronized void alert(JsonArray announcements)
	{
		Set<String> skip = ids(TsgHubSession.ANNOUNCEMENTS_ALERTED);
		skip.addAll(readIds());
		List<JsonObject> fresh = unread(announcements, skip);
		if (fresh.isEmpty()) return;
		Set<String> alerted = new LinkedHashSet<>();
		for (JsonObject announcement : TsgHubJson.objects(announcements))
		{
			String id = TsgHubJson.str(announcement, "id");
			if (skip.contains(id) || fresh.contains(announcement)) alerted.add(id);
		}
		plugin.session().set(TsgHubSession.ANNOUNCEMENTS_ALERTED, String.join(",", alerted));
		for (String line : chatLines(fresh)) chat.accept(line);
	}

	void onLoggedOut()
	{
		list = null;
	}

	int unreadCount()
	{
		JsonArray current = list;
		return current == null ? 0 : unread(current, readIds()).size();
	}

	boolean isUnread(String id)
	{
		return !readIds().contains(id);
	}

	void markRead()
	{
		JsonArray current = list;
		if (current == null) return;
		Set<String> ids = new LinkedHashSet<>();
		for (JsonObject announcement : TsgHubJson.objects(current)) ids.add(TsgHubJson.str(announcement, "id"));
		plugin.session().set(TsgHubSession.ANNOUNCEMENTS_READ, String.join(",", ids));
	}

	private Set<String> readIds()
	{
		return ids(TsgHubSession.ANNOUNCEMENTS_READ);
	}

	private Set<String> ids(String key)
	{
		String stored = plugin.session().get(key);
		return stored.isEmpty() ? new LinkedHashSet<>() : new LinkedHashSet<>(Arrays.asList(stored.split(",")));
	}

	static List<JsonObject> unread(JsonArray announcements, Set<String> read)
	{
		List<JsonObject> out = new ArrayList<>();
		for (JsonObject announcement : TsgHubJson.objects(announcements))
			if (!read.contains(TsgHubJson.str(announcement, "id"))) out.add(announcement);
		return out;
	}

	static List<String> chatLines(List<JsonObject> fresh)
	{
		List<String> lines = new ArrayList<>();
		for (int i = 0; i < fresh.size() && i < MAX_CHAT_LINES; i++)
			lines.add(TsgHubJson.str(fresh.get(i), "title"));
		int more = fresh.size() - MAX_CHAT_LINES;
		if (more > 0) lines.add("+" + TsgHubFormat.plural(more, "more announcement") + " in the TSG Hub sidebar.");
		return lines;
	}

	static JsonObject poll(JsonObject announcement)
	{
		return announcement != null && announcement.has("poll") && announcement.get("poll").isJsonObject() ? announcement.getAsJsonObject("poll") : null;
	}

	static List<Integer> myVote(JsonObject poll)
	{
		List<Integer> picks = new ArrayList<>();
		for (JsonElement pick : TsgHubJson.array(poll, "myVote")) if (pick.isJsonPrimitive()) picks.add(pick.getAsInt());
		return picks;
	}

	void vote(String id, List<Integer> options, Consumer<String> failed)
	{
		String hash = plugin.accountHash();
		if (hash.isEmpty() || !plugin.canUseHub() || executor.isShutdown())
		{
			failed.accept("Log in to vote.");
			return;
		}
		JsonObject request = adminBody();
		request.addProperty("accountHash", hash);
		JsonArray picks = new JsonArray();
		for (int option : options) picks.add(option);
		request.add("options", picks);
		api.get().call("POST", path(id) + "/vote", null, request).whenCompleteAsync((response, error) -> {
			try
			{
				TsgHubApi.result(response, error);
				if (!plugin.live()) load();
			}
			catch (Exception e)
			{
				String message = "Couldn't vote. " + TsgHubFormat.friendlyError(e);
				SwingUtilities.invokeLater(() -> failed.accept(message));
			}
		}, executor);
	}

	void save(String id, String title, String body, boolean pinned, Integer expiresInHours, JsonElement poll, boolean publish)
	{
		JsonObject request = adminBody();
		request.addProperty("title", title);
		request.addProperty("body", body);
		request.addProperty("pinned", pinned);
		if (expiresInHours != null) request.addProperty("expiresInHours", expiresInHours);
		if (poll != null) request.add("poll", poll);
		String success = publish ? "Announcement published." : "Saved.";
		if (id.isEmpty())
		{
			request.addProperty("draft", !publish);
			submit(success, true, token -> api.get().call("POST", "/v1/announcements", token, request).thenApply(TsgHubAnnouncements::announcementId));
			return;
		}
		submit(success, true, token -> api.get().call("PATCH", path(id), token, request)
			.thenCompose(saved -> publish ? api.get().call("POST", path(id) + "/publish", token, adminBody()) : CompletableFuture.completedFuture(saved))
			.thenApply(done -> id));
	}

	void publish(String id)
	{
		submit("Announcement published.", false, token -> api.get().call("POST", path(id) + "/publish", token, adminBody()).thenApply(TsgHubAnnouncements::announcementId));
	}

	void setPinned(String id, boolean pinned)
	{
		JsonObject request = adminBody();
		request.addProperty("pinned", pinned);
		submit(pinned ? "Pinned." : "Unpinned.", false, token -> api.get().call("PATCH", path(id), token, request).thenApply(TsgHubAnnouncements::announcementId));
	}

	void delete(String id)
	{
		String clan = TsgHubApi.encode(plugin.getDetectedClanName());
		submit("Announcement deleted.", false, token -> api.get().call("DELETE", path(id) + "?clanName=" + clan, token, null).thenApply(done -> ""));
	}

	private static String path(String id)
	{
		return "/v1/announcements/" + TsgHubApi.encode(id);
	}

	private static String announcementId(JsonObject result)
	{
		return TsgHubJson.str(TsgHubJson.object(result, "announcement"), "id");
	}

	private JsonObject adminBody()
	{
		JsonObject body = new JsonObject();
		body.addProperty("clanName", plugin.getDetectedClanName());
		return body;
	}

	private void submit(String success, boolean form, Function<String, CompletableFuture<String>> write)
	{
		String token = plugin.adminKey();
		if (token.isEmpty() || executor.isShutdown())
		{
			status("Announcements need a hub key with admin access.", Tone.ERROR);
			if (form) SwingUtilities.invokeLater(() -> panel.get().failed());
			return;
		}
		status("Saving...", Tone.INFO);
		write.apply(token).whenCompleteAsync((id, error) -> {
			if (error != null)
			{
				status("Couldn't save. " + TsgHubFormat.friendlyError(error), Tone.ERROR);
				if (form) SwingUtilities.invokeLater(() -> panel.get().failed());
				return;
			}
			status(success, Tone.SUCCESS);
			if (form) SwingUtilities.invokeLater(() -> panel.get().showAnnouncement(id));
			if (!plugin.live()) load();
		}, executor);
	}

	private void status(String message, Tone tone)
	{
		SwingUtilities.invokeLater(() -> {
			TsgHubNewsEditor admin = panel.get();
			if (admin != null) admin.setStatus(message, tone);
		});
	}
}

package com.tsghub;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CompletionException;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

final class TsgHubApi
{
	static final class HttpError extends IllegalStateException
	{
		final int status;

		HttpError(int status, String message)
		{
			super(message);
			this.status = status;
		}
	}

	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	private final String baseUrl;
	private final OkHttpClient http;
	private final Gson gson;
	private final Map<String, CompletableFuture<JsonObject>> inFlight = new ConcurrentHashMap<>();

	TsgHubApi(OkHttpClient http, Gson gson, String baseUrl)
	{
		this.gson = gson;
		this.baseUrl = baseUrl.replaceAll("/+$", "");
		this.http = http.newBuilder()
			.connectTimeout(5, TimeUnit.SECONDS)
			.readTimeout(8, TimeUnit.SECONDS)
			.build();
	}

	JsonObject request(String method, String path, String token, JsonObject payload) throws Exception
	{
		try (Response response = http.newCall(build(method, path, token, payload)).execute())
		{
			return read(response);
		}
	}

	CompletableFuture<JsonObject> call(String method, String path, String token, JsonObject payload)
	{
		if (!"GET".equals(method)) return send(method, path, token, payload);
		String key = path + " " + (token == null ? "" : token);
		CompletableFuture<JsonObject> shared = inFlight.computeIfAbsent(key, k -> {
			CompletableFuture<JsonObject> started = send(method, path, token, null);
			started.whenComplete((result, error) -> inFlight.remove(k, started));
			return started;
		});
		return shared.thenApply(JsonObject::deepCopy);
	}

	static JsonObject result(JsonObject value, Throwable error) throws Exception
	{
		if (error == null) return value;
		Throwable cause = error instanceof CompletionException && error.getCause() != null ? error.getCause() : error;
		if (cause instanceof Exception) throw (Exception) cause;
		throw new IllegalStateException(cause);
	}

	private CompletableFuture<JsonObject> send(String method, String path, String token, JsonObject payload)
	{
		CompletableFuture<JsonObject> future = new CompletableFuture<>();
		http.newCall(build(method, path, token, payload)).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				future.completeExceptionally(e);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (response)
				{
					future.complete(read(response));
				}
				catch (Exception e) { future.completeExceptionally(e); }
			}
		});
		return future;
	}

	private Request build(String method, String path, String token, JsonObject payload)
	{
		Request.Builder builder = new Request.Builder()
			.url(baseUrl + path)
			.header("Accept", "application/json")
			.header(TsgHubVersion.HEADER, TsgHubVersion.VERSION);
		if (token != null && !token.isEmpty()) builder.header("Authorization", "Bearer " + token);
		RequestBody body = payload == null ? null : RequestBody.create(JSON, payload.toString());
		// OkHttp requires a body for POST/PATCH/PUT.
		if (body == null && !"GET".equals(method) && !"DELETE".equals(method)) body = RequestBody.create(JSON, "{}");
		return builder.method(method, body).build();
	}

	private JsonObject read(Response response) throws IOException
	{
		ResponseBody responseBody = response.body();
		String text = responseBody == null ? "" : responseBody.string();
		JsonObject json = parseObject(text);
		if (!response.isSuccessful())
		{
			String message = json != null && json.has("error") && json.get("error").isJsonPrimitive()
				? json.get("error").getAsString()
				: "Service returned HTTP " + response.code();
			throw new HttpError(response.code(), message);
		}
		if (json == null) throw new IllegalStateException("Service returned an unexpected response");
		return json;
	}

	static String encode(String value)
	{
		return URLEncoder.encode(value == null ? "" : value, StandardCharsets.UTF_8);
	}

	private JsonObject parseObject(String text)
	{
		if (text.isEmpty()) return new JsonObject();
		try
		{
			JsonElement element = gson.fromJson(text, JsonElement.class);
			return element != null && element.isJsonObject() ? element.getAsJsonObject() : null;
		}
		catch (JsonParseException e) { return null; }
	}
}

package com.tsghub;

import java.util.concurrent.ThreadLocalRandom;

final class TsgHubBackoff
{
	private final long minMillis;
	private final long maxMillis;
	private int attempts;

	TsgHubBackoff(long minMillis, long maxMillis)
	{
		this.minMillis = minMillis;
		this.maxMillis = maxMillis;
	}

	synchronized long next()
	{
		long ceiling = Math.min(maxMillis, minMillis << Math.min(attempts++, 16));
		return ceiling / 2 + ThreadLocalRandom.current().nextLong(ceiling / 2 + 1);
	}

	synchronized void reset()
	{
		attempts = 0;
	}
}

package com.tsghub;

import static com.tsghub.TsgHubEvents.*;
import static com.tsghub.TsgHubHtml.*;
import static com.tsghub.TsgHubJson.*;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.function.UnaryOperator;

final class TsgHubBingo
{
	private TsgHubBingo()
	{
	}

	static JsonObject bestSet(JsonObject progress)
	{
		JsonObject best = null;
		for (JsonObject alt : objects(array(progress, "alternatives")))
		{
			if (best == null || share(alt) > share(best) || share(alt) == share(best) && integer(alt, "progress", 0) > integer(best, "progress", 0)) best = alt;
		}
		return best;
	}

	private static double share(JsonObject alt)
	{
		return integer(alt, "progress", 0) / (double) Math.max(1, integer(alt, "target", 1));
	}

	static String setName(JsonObject alt)
	{
		String name = TsgHubItemSets.nameFor(itemIds(array(alt, "items")));
		return name.isEmpty() ? "Set " + integer(alt, "group", 1) : name;
	}

	static List<Integer> itemIds(JsonArray items)
	{
		List<Integer> ids = new ArrayList<>();
		for (JsonObject item : objects(items)) ids.add(integer(item, "id", 0));
		return ids;
	}

	static final class SetLine
	{
		final String name;
		final int have;
		final int target;
		final List<String> found = new ArrayList<>();
		final List<String> finders = new ArrayList<>();
		final List<String> needed = new ArrayList<>();

		SetLine(String name, int have, int target)
		{
			this.name = name;
			this.have = have;
			this.target = target;
		}

		String foundText()
		{
			List<String> parts = new ArrayList<>();
			for (int i = 0; i < found.size(); i++) parts.add(finders.get(i).isEmpty() ? found.get(i) : found.get(i) + " (" + finders.get(i) + ")");
			return String.join(", ", parts);
		}

		String foundHtml(String self)
		{
			List<String> parts = new ArrayList<>();
			for (int i = 0; i < found.size(); i++)
			{
				String piece = escape(found.get(i));
				parts.add(finders.get(i).isEmpty() ? piece : piece + " (" + nameHtml(finders.get(i), self) + ")");
			}
			return String.join(", ", parts);
		}
	}

	static List<SetLine> setLines(JsonObject source, boolean withFinders)
	{
		List<JsonObject> options = objects(array(source, "alternatives"));
		if (options.isEmpty() && source.has("items"))
		{
			JsonObject single = new JsonObject();
			single.add("items", array(source, "items"));
			single.addProperty("progress", array(source, "items").size() - missingPieces(array(source, "items")).size());
			single.addProperty("target", array(source, "items").size());
			options.add(single);
		}
		options.sort((a, b) -> {
			int byShare = Double.compare(share(b), share(a));
			return byShare != 0 ? byShare : Integer.compare(integer(b, "progress", 0), integer(a, "progress", 0));
		});
		List<SetLine> lines = new ArrayList<>();
		for (JsonObject option : options)
		{
			boolean legacy = !option.has("group");
			String name = legacy ? "Pieces" : setName(option);
			SetLine line = new SetLine(name, integer(option, "progress", 0), integer(option, "target", 1));
			String prefix = legacy || name.startsWith("Set ") ? "" : name + " ";
			for (JsonObject item : objects(array(option, "items")))
			{
				String piece = str(item, "name");
				if (!prefix.isEmpty() && piece.toLowerCase(Locale.ROOT).startsWith(prefix.toLowerCase(Locale.ROOT))) piece = piece.substring(prefix.length());
				if (bool(item, "complete"))
				{
					line.found.add(piece);
					line.finders.add(withFinders ? str(item, "obtainedBy") : "");
				}
				else line.needed.add(piece);
			}
			lines.add(line);
		}
		return lines;
	}

	static List<String> missingPieces(JsonArray items)
	{
		List<String> missing = new ArrayList<>();
		for (JsonObject item : objects(items)) if (!bool(item, "complete")) missing.add(str(item, "name"));
		return missing;
	}

	static String contributorsText(JsonObject progress, String separator, int max)
	{
		return contributors(progress, separator, max, name -> name);
	}

	static String contributorsHtml(JsonObject progress, String separator, int max, String self)
	{
		return contributors(progress, separator, max, name -> nameHtml(name, self));
	}

	private static String contributors(JsonObject progress, String separator, int max, UnaryOperator<String> name)
	{
		JsonArray contributors = array(progress, "contributors");
		if (contributors.size() == 0) return "";
		List<String> parts = new ArrayList<>();
		for (int i = 0; i < Math.min(max, contributors.size()); i++)
		{
			JsonObject entry = contributors.get(i).getAsJsonObject();
			parts.add(name.apply(str(entry, "displayName")) + " " + integer(entry, "amount", 1));
		}
		if (contributors.size() > max) parts.add("+" + (contributors.size() - max));
		return String.join(separator, parts);
	}

	static String completedLine(JsonObject progress)
	{
		String scope = str(progress, "scope");
		String by = str(progress, "completedBy");
		boolean creditedToOrganizer = creditedToOrganizer(progress);
		if (creditedToOrganizer) return "Completed (credited to no one)";
		if ("individual".equals(scope) || by.isEmpty()) return "Completed";
		if (!"solo".equals(scope) && array(progress, "contributors").size() > 0) return "Completed";
		return "Completed by " + by;
	}
}

package com.tsghub;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.JLabel;
import javax.swing.JTextField;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.hiscore.HiscoreSkillType;

final class TsgHubBossPicker extends TsgHubSearchField
{
	static final List<String> BOSSES = bossNames();
	private static final String DEFAULT_HINT = "Type to search bosses, or enter any name shown in its kill count message.";

	private final JLabel hint = TsgHubUi.caption(DEFAULT_HINT);
	private final Runnable onChosen;

	TsgHubBossPicker(String caption, Runnable onChosen)
	{
		super(new JTextField());
		this.onChosen = onChosen;
		add(TsgHubUi.caption(caption));
		add(Box.createVerticalStrut(TsgHubTheme.GAP_XS));
		addSearch("e.g. Vorkath");
		add(hint);
		setBorder(BorderFactory.createEmptyBorder(0, 0, 10, 0));
	}

	@Override
	boolean isExact(String query)
	{
		return BOSSES.stream().anyMatch(b -> b.equalsIgnoreCase(query));
	}

	@Override
	List<String> matches(String query)
	{
		String lower = query.toLowerCase(Locale.ROOT);
		List<String> prefix = new ArrayList<>();
		List<String> contains = new ArrayList<>();
		for (String boss : BOSSES)
		{
			String name = boss.toLowerCase(Locale.ROOT);
			if (name.startsWith(lower) || name.contains(" " + lower)) prefix.add(boss);
			else if (name.contains(lower)) contains.add(boss);
		}
		prefix.addAll(contains);
		return prefix;
	}

	@Override
	void resultsChanged(String query, int matches)
	{
		if (matches > 0) hint.setText("Click a boss (or press Enter) to pick it.");
		else if (!query.isEmpty() && isExact(query)) hint.setText("Counts \"" + query + "\" kill count messages.");
		else if (matches == 0 && !query.isEmpty()) hint.setText("Not in RuneLite's boss list. It will still count if this name appears in the kill count message.");
		else hint.setText(DEFAULT_HINT);
	}

	@Override
	void chosen()
	{
		if (onChosen != null) onChosen.run();
	}

	private static List<String> bossNames()
	{
		List<String> names = new ArrayList<>();
		for (HiscoreSkill skill : HiscoreSkill.values())
		{
			if (skill.getType() != HiscoreSkillType.BOSS) continue;
			String name = skill.getName();
			if (name.startsWith("Chambers of Xeric") || name.startsWith("Theatre of Blood") || name.startsWith("Tombs of Amascut")) continue;
			names.add(name);
		}
		names.sort(String.CASE_INSENSITIVE_ORDER);
		return names;
	}
}

