package com.tsghub;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.GridLayout;
import java.time.DayOfWeek;
import java.time.LocalDate;
import java.time.YearMonth;
import java.time.format.DateTimeFormatter;
import java.time.format.TextStyle;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.SwingConstants;

final class TsgHubDatePicker extends JButton
{
	private static final DateTimeFormatter DISPLAY = DateTimeFormatter.ofPattern("EEE, MMM d, yyyy");
	private LocalDate date = LocalDate.now();
	private YearMonth shownMonth = YearMonth.now();
	private final List<Runnable> listeners = new ArrayList<>();
	private final JPopupMenu popup = new JPopupMenu();
	private final JLabel monthLabel = TsgHubUi.boldLabel("");
	private final JPanel grid = new JPanel(new GridLayout(0, 7, 2, 2));

	TsgHubDatePicker()
	{
		setHorizontalAlignment(SwingConstants.LEFT);
		setIcon(new CalendarIcon());
		setIconTextGap(8);
		setFocusPainted(false);
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		setToolTipText("Pick a date");
		addActionListener(e -> open());
		buildPopup();
		refreshText();
	}

	LocalDate getDate()
	{
		return date;
	}

	void setDate(LocalDate value)
	{
		date = value == null ? LocalDate.now() : value;
		refreshText();
	}

	void onChange(Runnable listener)
	{
		listeners.add(listener);
	}

	private void refreshText()
	{
		setText(date.format(DISPLAY));
	}

	private void buildPopup()
	{
		JPanel panel = new JPanel(new BorderLayout(0, 6));
		panel.setBackground(TsgHubTheme.CARD);
		panel.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
		JPanel header = new JPanel(new BorderLayout());
		header.setOpaque(false);
		JButton previous = navButton("<", -1);
		JButton next = navButton(">", 1);
		monthLabel.setHorizontalAlignment(SwingConstants.CENTER);
		header.add(previous, BorderLayout.WEST);
		header.add(monthLabel, BorderLayout.CENTER);
		header.add(next, BorderLayout.EAST);
		panel.add(header, BorderLayout.NORTH);
		grid.setOpaque(false);
		panel.add(grid, BorderLayout.CENTER);
		popup.setBorder(BorderFactory.createLineBorder(TsgHubTheme.BORDER));
		popup.add(panel);
	}

	private JButton navButton(String text, int months)
	{
		JButton button = TsgHubUi.button(text);
		button.setMargin(new java.awt.Insets(2, 8, 2, 8));
		button.addActionListener(e -> {
			shownMonth = shownMonth.plusMonths(months);
			renderMonth();
		});
		return button;
	}

	private void open()
	{
		shownMonth = YearMonth.from(date);
		renderMonth();
		popup.show(this, 0, getHeight());
	}

	private void renderMonth()
	{
		monthLabel.setText(shownMonth.getMonth().getDisplayName(TextStyle.FULL, Locale.getDefault()) + " " + shownMonth.getYear());
		grid.removeAll();
		for (int i = 0; i < 7; i++)
		{
			DayOfWeek day = DayOfWeek.SUNDAY.plus(i);
			JLabel name = TsgHubUi.caption(day.getDisplayName(TextStyle.SHORT, Locale.getDefault()).substring(0, 2));
			name.setHorizontalAlignment(SwingConstants.CENTER);
			grid.add(name);
		}
		int leading = shownMonth.atDay(1).getDayOfWeek().getValue() % 7; // Sunday first
		for (int i = 0; i < leading; i++) grid.add(new JLabel());
		LocalDate today = LocalDate.now();
		for (int d = 1; d <= shownMonth.lengthOfMonth(); d++)
		{
			LocalDate day = shownMonth.atDay(d);
			JButton cell = new JButton(String.valueOf(d));
			cell.setFocusPainted(false);
			cell.setMargin(new java.awt.Insets(2, 2, 2, 2));
			cell.setPreferredSize(new Dimension(34, 26));
			cell.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
			boolean selected = day.equals(date);
			cell.setBackground(selected ? TsgHubTheme.ACCENT.darker() : TsgHubTheme.BACKGROUND);
			cell.setForeground(selected ? Color.WHITE : TsgHubTheme.TEXT);
			if (day.equals(today) && !selected) cell.setBorder(BorderFactory.createLineBorder(TsgHubTheme.ACCENT));
			cell.addActionListener(e -> {
				date = day;
				refreshText();
				popup.setVisible(false);
				listeners.forEach(Runnable::run);
			});
			grid.add(cell);
		}
		grid.revalidate();
		grid.repaint();
		popup.pack();
	}

	private static final class CalendarIcon implements javax.swing.Icon
	{
		@Override public int getIconWidth() { return 14; }
		@Override public int getIconHeight() { return 14; }
		@Override public void paintIcon(Component c, java.awt.Graphics graphics, int x, int y)
		{
			Graphics2D g = (Graphics2D) graphics.create();
			g.translate(x, y);
			g.setColor(TsgHubTheme.MUTED);
			g.drawRect(1, 2, 12, 11);
			g.fillRect(1, 2, 13, 3);
			g.fillRect(4, 0, 2, 3);
			g.fillRect(9, 0, 2, 3);
			for (int row = 0; row < 2; row++)
				for (int col = 0; col < 3; col++) g.fillRect(3 + col * 3, 7 + row * 3, 2, 2);
			g.dispose();
		}
	}
}

package com.tsghub;

import static com.tsghub.TsgHubFormat.*;
import static com.tsghub.TsgHubIcons.*;
import static com.tsghub.TsgHubSession.DOCK_COLLAPSED;
import static com.tsghub.TsgHubSession.DOCK_SPLIT;
import static com.tsghub.TsgHubTheme.*;
import static com.tsghub.TsgHubUi.*;

import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Graphics;
import java.awt.Graphics2D;
import javax.swing.BorderFactory;
import javax.swing.Icon;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JSplitPane;
import javax.swing.Timer;
import javax.swing.plaf.basic.BasicSplitPaneDivider;
import javax.swing.plaf.basic.BasicSplitPaneUI;

final class TsgHubDock extends JPanel
{
	private static final double DEFAULT_SPLIT = 0.55;
	private static final double MIN_SPLIT = 0.2;
	private static final double MAX_SPLIT = 0.8;
	private static final int DIVIDER = 9;

	private final JComponent main;
	private final JSplitPane split = new JSplitPane(JSplitPane.VERTICAL_SPLIT)
	{
		@Override
		public void doLayout()
		{
			int span = getHeight() - getDividerSize();
			if (applySplit && span > 0)
			{
				applySplit = false;
				setDividerLocation((int) Math.round(span * splitRatio()));
			}
			super.doLayout();
		}
	};
	private final JPanel pane = panel(new BorderLayout(0, 4));
	private final JPanel bar = new JPanel(new BorderLayout(6, 0));
	private final JLabel icon = new JLabel();
	private final JLabel title = boldLabel(" ");
	private final JLabel subtitle = shrinkable(caption(" "));
	private final ChevronIcon chevron = new ChevronIcon();
	private final JButton toggle = iconButton(chevron, "Collapse");
	private final JButton close = iconButton(new CloseIcon(), "Unpin");
	private JComponent content;
	private final TsgHubSession session;
	private final Timer saveTimer = new Timer(500, e -> saveSplit());
	private boolean collapsed;
	private boolean shown = true;
	private boolean applySplit;

	TsgHubDock(JComponent main, Runnable onUnpin, TsgHubSession session)
	{
		super(new BorderLayout());
		this.main = main;
		this.session = session;
		saveTimer.setRepeats(false);
		collapsed = "true".equals(session.get(DOCK_COLLAPSED));
		setOpaque(false);

		bar.setBackground(CARD);
		bar.setBorder(BorderFactory.createEmptyBorder(3, 7, 3, 3));
		JPanel titles = panel(new BorderLayout(6, 0));
		titles.add(title, BorderLayout.WEST);
		titles.add(subtitle, BorderLayout.CENTER);
		bar.add(icon, BorderLayout.WEST);
		bar.add(titles, BorderLayout.CENTER);
		JPanel buttons = panel(new FlowLayout(FlowLayout.RIGHT, 0, 0));
		buttons.add(toggle);
		buttons.add(close);
		bar.add(buttons, BorderLayout.EAST);
		clickable(bar, this::toggle);
		toggle.addActionListener(e -> toggle());
		close.addActionListener(e -> onUnpin.run());
		pane.add(bar, BorderLayout.NORTH);

		split.setBorder(BorderFactory.createEmptyBorder());
		split.setOpaque(false);
		split.setContinuousLayout(true);
		split.setDividerSize(DIVIDER);
		split.setResizeWeight(splitRatio());
		split.setUI(new BasicSplitPaneUI()
		{
			@Override
			public BasicSplitPaneDivider createDefaultDivider()
			{
				return new Grip(this);
			}
		});
		split.addPropertyChangeListener(JSplitPane.DIVIDER_LOCATION_PROPERTY, e -> saveTimer.restart());
		rebuild();
	}

	void pin(Icon pinIcon, JComponent next)
	{
		icon.setIcon(new SmallIcon(pinIcon));
		content = next;
		rebuild();
	}

	void unpin()
	{
		content = null;
		rebuild();
	}

	void setTitle(String text, String detail)
	{
		title.setText(text);
		subtitle.setText(detail.isEmpty() ? " " : "· " + detail);
		bar.setToolTipText(detail.isEmpty() ? text : text + " · " + detail);
	}

	void setShown(boolean next)
	{
		if (shown == next) return;
		shown = next;
		rebuild();
	}

	void expand()
	{
		if (!collapsed) return;
		toggle();
	}

	private void toggle()
	{
		collapsed = !collapsed;
		session.set(DOCK_COLLAPSED, collapsed ? "true" : "");
		rebuild();
	}

	private void rebuild()
	{
		removeAll();
		pane.removeAll();
		pane.add(bar, BorderLayout.NORTH);
		if (content == null || !shown)
		{
			add(main, BorderLayout.CENTER);
		}
		else if (collapsed)
		{
			add(main, BorderLayout.CENTER);
			JPanel south = panel(new BorderLayout());
			south.setBorder(BorderFactory.createEmptyBorder(6, 0, 0, 0));
			south.add(bar, BorderLayout.CENTER);
			add(south, BorderLayout.SOUTH);
		}
		else
		{
			pane.add(content, BorderLayout.CENTER);
			content.setVisible(true);
			main.setMinimumSize(new Dimension(0, 60));
			pane.setMinimumSize(new Dimension(0, 60));
			split.setTopComponent(main);
			split.setBottomComponent(pane);
			applySplit = true;
			add(split, BorderLayout.CENTER);
		}
		chevron.down = !collapsed;
		toggle.setToolTipText(collapsed ? "Expand" : "Collapse");
		revalidate();
		repaint();
	}

	private double splitRatio()
	{
		try
		{
			double ratio = Double.parseDouble(session.get(DOCK_SPLIT));
			return Math.max(MIN_SPLIT, Math.min(MAX_SPLIT, ratio));
		}
		catch (NumberFormatException e)
		{
			return DEFAULT_SPLIT;
		}
	}

	private void saveSplit()
	{
		int span = split.getHeight() - split.getDividerSize();
		if (applySplit || span <= 0 || split.getParent() == null) return;
		double ratio = Math.max(MIN_SPLIT, Math.min(MAX_SPLIT, split.getDividerLocation() / (double) span));
		split.setResizeWeight(ratio);
		session.set(DOCK_SPLIT, String.format(java.util.Locale.ROOT, "%.3f", ratio));
	}

	private static final class Grip extends BasicSplitPaneDivider
	{
		Grip(BasicSplitPaneUI ui)
		{
			super(ui);
			setBorder(null);
		}

		@Override
		public void paint(Graphics graphics)
		{
			Graphics2D g = (Graphics2D) graphics.create();
			g.setColor(BACKGROUND);
			g.fillRect(0, 0, getWidth(), getHeight());
			int y = getHeight() / 2;
			g.setColor(BORDER);
			g.fillRect(0, y, getWidth(), 1);
			g.setColor(MUTED);
			int x = getWidth() / 2;
			g.fillRoundRect(x - 12, y - 1, 24, 3, 3, 3);
			g.dispose();
		}
	}

	private static final class SmallIcon implements Icon
	{
		private static final double SCALE = 2 / 3.0;
		private final Icon icon;

		SmallIcon(Icon icon) { this.icon = icon; }
		@Override public int getIconWidth() { return (int) Math.round(icon.getIconWidth() * SCALE); }
		@Override public int getIconHeight() { return (int) Math.round(icon.getIconHeight() * SCALE); }

		@Override
		public void paintIcon(Component c, Graphics graphics, int x, int y)
		{
			Graphics2D g = (Graphics2D) graphics.create();
			g.translate(x, y);
			g.scale(SCALE, SCALE);
			icon.paintIcon(c, g, 0, 0);
			g.dispose();
		}
	}

	private static final class ChevronIcon extends HoverIcon
	{
		private boolean down = true;

		ChevronIcon() { super(16); }
		@Override void paint(Graphics2D g, Component c)
		{
			if (down)
			{
				g.drawLine(4, 6, 8, 10);
				g.drawLine(8, 10, 12, 6);
			}
			else
			{
				g.drawLine(4, 10, 8, 6);
				g.drawLine(8, 6, 12, 10);
			}
		}
	}

	private static final class CloseIcon extends HoverIcon
	{
		CloseIcon() { super(16); }
		@Override void paint(Graphics2D g, Component c)
		{
			g.drawLine(5, 5, 11, 11);
			g.drawLine(11, 5, 5, 11);
		}
	}
}

package com.tsghub;

import static com.tsghub.PlayerNames.*;
import static com.tsghub.TsgHubBingo.*;
import static com.tsghub.TsgHubFormat.*;
import static com.tsghub.TsgHubHtml.*;
import static com.tsghub.TsgHubJson.*;
import static com.tsghub.TsgHubTheme.*;
import static com.tsghub.TsgHubUi.*;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.tsghub.TsgHubUi.Tone;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.util.ArrayList;
import java.util.AbstractMap;
import java.util.ArrayDeque;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.function.Function;
import java.util.function.Supplier;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.util.Text;

final class TsgHubDrops
{
	private static final Set<String> COX_ITEMS = Set.of(
		"Dexterous prayer scroll", "Arcane prayer scroll", "Twisted buckler", "Dragon hunter crossbow",
		"Dinh's bulwark", "Ancestral hat", "Ancestral robe top", "Ancestral robe bottom", "Dragon claws",
		"Elder maul", "Kodai insignia", "Twisted bow", "Olmlet", "Metamorphic dust", "Twisted ancestral colour kit");
	private static final Set<String> TOB_ITEMS = Set.of(
		"Avernic defender hilt", "Ghrazi rapier", "Sanguinesti staff", "Justiciar faceguard", "Justiciar chestguard",
		"Justiciar legguards", "Scythe of vitur", "Lil' zik", "Sanguine dust", "Sanguine ornament kit", "Holy ornament kit");
	private static final Set<String> TOA_ITEMS = Set.of(
		"Osmumten's fang", "Lightbearer", "Elidinis' ward", "Masori mask", "Masori body", "Masori chaps",
		"Tumeken's shadow", "Tumeken's guardian", "Thread of Elidinis", "Breach of the scarab", "Eye of the corruptor",
		"Jewel of the sun", "Menaphite ornament kit", "Remnant of Akkha",
		"Remnant of Ba-Ba", "Remnant of Kephri", "Remnant of Zebak", "Ancient remnant");
	static final int REFRESH_SECONDS = 60;
	private static final int INDEX_CHUNK = 2000;

	private final TsgHubPlugin plugin;
	private final Client client;
	private final ClientThread clientThread;
	private final ScheduledExecutorService executor;
	private final Supplier<TsgHubApi> api;
	private final Supplier<TsgHubSidebarPanel> sidebar;
	private final Map<String, Integer> itemIds = new HashMap<>();
	private int indexedItems;
	private final Recent<JsonObject> lootSources = new Recent<>();
	private final Recent<String> countMessages = new Recent<>();

	TsgHubDrops(TsgHubPlugin plugin, Client client, ClientThread clientThread, ScheduledExecutorService executor, Supplier<TsgHubApi> api, Supplier<TsgHubSidebarPanel> sidebar)
	{
		this.plugin = plugin;
		this.client = client;
		this.clientThread = clientThread;
		this.executor = executor;
		this.api = api;
		this.sidebar = sidebar;
	}

	void onLoot(String source, List<String> items)
	{
		if (source == null || source.isEmpty() || !plugin.sharingEnabled()) return;
		JsonObject loot = new JsonObject();
		loot.addProperty("source", source);
		JsonArray names = new JsonArray();
		items.forEach(names::add);
		loot.add("items", names);
		lootSources.add(client.getTickCount(), loot);
	}

	void onChatMessage(ChatMessage event)
	{
		if (!plugin.sharingEnabled()) return;
		if (event.getType() == ChatMessageType.GAMEMESSAGE)
		{
			String text = Text.removeTags(event.getMessage()).trim();
			String lower = text.toLowerCase(Locale.ROOT);
			if (TsgHubRules.get().dropContext.stream().anyMatch(lower::contains)) countMessages.add(client.getTickCount(), text);
			return;
		}
		if (event.getType() != ChatMessageType.CLAN_MESSAGE) return;
		String message = broadcast(event.getMessage());
		long hash = client.getAccountHash();
		if (message == null || hash == -1 || executor.isShutdown()) return;
		String self = plugin.getDetectedPlayerName();
		JsonObject body = new JsonObject();
		body.addProperty("clanName", plugin.getDetectedClanName());
		body.addProperty("accountHash", Long.toString(hash));
		body.addProperty("message", message);
		body.addProperty("reporter", self);
		int tick = client.getTickCount();
		body.addProperty("tick", tick);
		executor.schedule(() -> {
			if (!plugin.sharingEnabled()) return;
			if (!fromSelf(message, self))
			{
				post(body);
				return;
			}
			JsonObject context = new JsonObject();
			int since = tick - TsgHubRules.get().dropContextTicks;
			context.add("loot", lootSources.since(since, JsonObject::deepCopy));
			context.add("chat", countMessages.since(since, text -> {
				JsonObject row = new JsonObject();
				row.addProperty("text", text);
				return row;
			}));
			body.add("context", context);
			post(body);
		}, TsgHubRules.get().dropDelayMs, TimeUnit.MILLISECONDS);
	}

	private void post(JsonObject body)
	{
		plugin.report("drop", "/v1/drops", body);
	}

	static boolean fromSelf(String message, String self)
	{
		if (self == null || self.isEmpty() || message.length() <= self.length() || message.charAt(self.length()) != ' ') return false;
		return samePlayer(message.substring(0, self.length()), self);
	}

	static String broadcast(String raw)
	{
		if (raw == null) return null;
		String message = Text.removeTags(raw).replace(' ', ' ').trim();
		String lower = message.toLowerCase(Locale.ROOT);
		for (String keyword : TsgHubRules.get().dropKeywords) if (lower.contains(keyword)) return message;
		return null;
	}

	void load(boolean quiet)
	{
		if (!plugin.isInHubClan() || !plugin.sharingEnabled() || executor.isShutdown()) return;
		String clan = TsgHubApi.encode(plugin.getDetectedClanName());
		String query = query();
		Runnable done = quiet ? null : () -> plugin.ui(s -> s.setBusy(false));
		if (!quiet) plugin.ui(s -> s.setBusy(true));
		api.get().call("GET", "/v1/drops?clanName=" + clan + query, null, null).whenCompleteAsync((response, error) -> {
			try
			{
				JsonArray drops = TsgHubApi.result(response, error).getAsJsonArray("drops");
				if (query.equals(query())) apply(drops, done);
				else if (done != null) done.run();
			}
			catch (Exception e)
			{
				if (quiet) return;
				plugin.ui(s -> s.setStatus("Couldn't load drops. " + TsgHubFormat.friendlyError(e), Tone.ERROR));
				plugin.ui(s -> s.setBusy(false));
			}
		}, executor);
	}

	void onSnapshot(JsonArray drops)
	{
		if (query().isEmpty()) apply(drops);
		else load(true);
	}

	private String query()
	{
		TsgHubSidebarPanel s = sidebar.get();
		return s == null ? "" : s.dropsQuery();
	}

	void apply(JsonArray drops)
	{
		apply(drops, null);
	}

	private void apply(JsonArray drops, Runnable done)
	{
		if (drops == null)
		{
			if (done != null) done.run();
			return;
		}
		if (clientThread == null)
		{
			plugin.ui(s -> s.setDrops(drops));
			return;
		}
		clientThread.invoke(() -> {
			if (!indexItems()) return false;
			addItemIds(drops);
			plugin.ui(s -> s.setDrops(drops));
			if (done != null) done.run();
			return true;
		});
	}

	private void addItemIds(JsonArray drops)
	{
		for (int i = 0; i < drops.size(); i++)
		{
			JsonObject drop = drops.get(i).getAsJsonObject();
			Integer id = itemIds.get(TsgHubJson.str(drop, "item").toLowerCase(Locale.ROOT));
			if (id != null) drop.addProperty("itemId", id);
		}
	}

	private boolean indexItems()
	{
		int end = Math.min(client.getItemCount(), indexedItems + INDEX_CHUNK);
		for (int id = indexedItems; id < end; id++)
		{
			ItemComposition item = client.getItemDefinition(id);
			if (item == null || item.getNote() != -1 || item.getPlaceholderTemplateId() != -1) continue;
			String name = item.getName();
			if (name == null || name.isEmpty() || "null".equalsIgnoreCase(name)) continue;
			itemIds.putIfAbsent(name.toLowerCase(Locale.ROOT), id);
		}
		indexedItems = end;
		return client.getItemCount() > 0 && end >= client.getItemCount();
	}

	void autoRefresh()
	{
		TsgHubSidebarPanel s = sidebar.get();
		if (s != null && s.wantsDrops()) load(true);
	}

	static String dropTooltip(JsonObject drop)
	{
		String source = str(drop, "source");
		String rate = str(drop, "rate");
		int kc = integer(drop, "killCount", 0);
		String out = "";
		if (!source.isEmpty())
		{
			out += tipSection(true, tipLine(MUTED, "<b>DROPPED BY</b>"))
				+ tipCard(ACCENT, "<b>" + escape(source) + "</b>" + (rate.isEmpty() ? "" : "<br>" + escape(rate) + tipLine(MUTED, " drop rate")));
		}
		if (kc > 0) out += tipSection(out.isEmpty(), tipLine(MUTED, "<b>KILL COUNT</b> ") + TsgHubFormat.number(kc));
		return out;
	}

	static boolean dropMatches(JsonObject drop, int type, long minValue, String self)
	{
		String kind = str(drop, "kind");
		boolean typeMatches;
		switch (type)
		{
			case 1: typeMatches = samePlayer(str(drop, "player"), self); break;
			case 2: typeMatches = "raid".equals(kind); break;
			case 3: typeMatches = "pet".equals(kind) || "dupe".equals(kind); break;
			case 4: typeMatches = bool(drop, "newLog") || "clog".equals(kind); break;
			default: typeMatches = true;
		}
		long value = drop.has("value") ? drop.get("value").getAsLong() : 0;
		return typeMatches && value >= minValue;
	}

	static List<String> dropTags(JsonObject drop)
	{
		List<String> tags = new ArrayList<>();
		String kind = str(drop, "kind");
		if ("raid".equals(kind)) tags.add(raidName(str(drop, "item")));
		else if ("pet".equals(kind)) tags.add("Pet");
		else if ("dupe".equals(kind)) tags.add("Dupe pet");
		if (bool(drop, "newLog") || "clog".equals(kind)) tags.add("Log");
		return tags;
	}

	static String raidName(String item)
	{
		String base = item.replaceAll("(\\s*\\([^)]*\\))+$", "");
		if (COX_ITEMS.contains(base)) return "CoX";
		if (TOB_ITEMS.contains(base)) return "ToB";
		if (TOA_ITEMS.contains(base)) return "ToA";
		return "Raid";
	}

	static String dropItem(JsonObject drop)
	{
		int quantity = integer(drop, "quantity", 1);
		String item = str(drop, "item").replaceAll("(\\s*\\([^)]*\\))+$", "");
		return quantity > 1 ? quantity + " x " + item : item;
	}

	static String dropAge(String iso, Instant now)
	{
		Instant then = TsgHubJson.instant(iso);
		if (then == null) return "";
		String elapsed = TsgHubFormat.elapsed(then, now);
		return elapsed.isEmpty() ? "now" : elapsed;
	}

	static String dropWhen(String iso, Instant now, ZoneId zone)
	{
		String day = dropDay(iso, now, zone);
		if ("Earlier".equals(day)) return "";
		if ("Today".equals(day)) return dropAge(iso, now);
		return Instant.parse(iso).atZone(zone).format(TsgHubFormat.CLOCK_24);
	}

	static String dropDay(String iso, Instant now, ZoneId zone)
	{
		Instant then;
		try { then = Instant.parse(iso); }
		catch (Exception e) { return "Earlier"; }
		LocalDate day = then.atZone(zone).toLocalDate();
		LocalDate today = now.atZone(zone).toLocalDate();
		if (!day.isBefore(today)) return "Today";
		if (day.equals(today.minusDays(1))) return "Yesterday";
		return localDate(then, zone);
	}

	static final class Recent<T>
	{
		private final ArrayDeque<Map.Entry<Integer, T>> seen = new ArrayDeque<>();

		synchronized void add(int tick, T value)
		{
			seen.addLast(new AbstractMap.SimpleImmutableEntry<>(tick, value));
			while (seen.size() > TsgHubRules.get().dropContextKeep) seen.removeFirst();
		}

		synchronized JsonArray since(int tick, Function<T, JsonObject> row)
		{
			JsonArray out = new JsonArray();
			for (Map.Entry<Integer, T> entry : seen)
			{
				if (entry.getKey() < tick) continue;
				JsonObject value = row.apply(entry.getValue());
				value.addProperty("tick", entry.getKey());
				out.add(value);
			}
			return out;
		}
	}
}

package com.tsghub;

import static com.tsghub.PlayerNames.*;
import static com.tsghub.TsgHubFormat.*;
import static com.tsghub.TsgHubJson.*;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonNull;
import com.google.gson.JsonObject;
import java.time.DateTimeException;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

final class TsgHubEvents
{
	private static final ZoneId CLAN_ZONE = ZoneId.of("Australia/Sydney");

	private TsgHubEvents()
	{
	}
	static boolean creditedToOrganizer(JsonObject progress)
	{
		return bool(progress, "override") && !bool(progress, "overrideCredited");
	}

	private static ZoneId eventZone(JsonObject event)
	{
		try { return ZoneId.of(str(event, "timeZone")); }
		catch (DateTimeException e) { return CLAN_ZONE; }
	}

	private static Instant midnight(String isoDate, ZoneId zone, int plusDays)
	{
		try { return LocalDate.parse(isoDate).plusDays(plusDays).atStartOfDay(zone).toInstant(); }
		catch (DateTimeException e) { return null; }
	}

	static Instant eventStart(JsonObject event)
	{
		Instant start = instant(str(event, "startsAt"));
		if (start == null) start = instant(str(eventConfig(event), "startsAt"));
		return start != null ? start : midnight(str(event, "startDate"), eventZone(event), 0);
	}

	static Instant eventEnd(JsonObject event)
	{
		Instant end = instant(str(event, "endsAt"));
		if (end != null || "drop-party".equals(str(event, "type"))) return end;
		return midnight(str(event, "endDate"), eventZone(event), 1);
	}

	static String eventWhen(JsonObject event)
	{
		return timeRange(eventStart(event), eventEnd(event), ZoneId.systemDefault(), clock.instant());
	}

	static String eventRelative(JsonObject event)
	{
		if ("ended".equals(str(event, "status"))) return "ended";
		return relativeTime(eventStart(event), eventEnd(event), clock.instant());
	}

	static String eventName(JsonObject event)
	{
		String type = str(event, "type");
		if ("skill".equals(type) || "boss".equals(type)) return eventTypeLabel(event);
		return str(event, "name");
	}

	static String eventCountdown(JsonObject event)
	{
		String relative = eventRelative(event);
		if (relative.startsWith("ends in ")) return relative.substring(8) + " left";
		if (relative.startsWith("starts ")) return relative.substring(7);
		return relative.isEmpty() ? "TBD" : capitalize(relative);
	}

	static String eventDetail(JsonObject event)
	{
		JsonObject config = eventConfig(event);
		switch (str(event, "type"))
		{
			case "skill": return skillName(str(config, "skill"));
			case "boss": return str(config, "npcName");
			case "drop-party":
				List<String> where = new ArrayList<>();
				if (integer(config, "world", 0) > 0) where.add("W" + integer(config, "world", 0));
				if (!str(config, "location").isEmpty()) where.add(str(config, "location"));
				return String.join(" · ", where);
			default: return eventDay(event);
		}
	}

	static long prizeTotal(List<Long> prizes)
	{
		long total = 0;
		for (long prize : prizes) total += prize;
		return total;
	}

	static List<Long> eventPrizes(JsonObject event)
	{
		List<Long> prizes = new ArrayList<>();
		for (JsonElement item : array(event, "prizes"))
			if (item.isJsonPrimitive() && item.getAsJsonPrimitive().isNumber() && item.getAsLong() > 0) prizes.add(item.getAsLong());
		return prizes;
	}

	static String prizeSummary(List<Long> prizes)
	{
		List<String> parts = new ArrayList<>();
		for (int i = 0; i < prizes.size(); i++) parts.add(place(i + 1) + " " + formatGp(prizes.get(i)));
		return String.join(" · ", parts);
	}

	static String eventStartWhen(JsonObject event)
	{
		Instant start = eventStart(event);
		if (start == null) return "";
		ZonedDateTime from = start.atZone(ZoneId.systemDefault());
		return when(from, clock.instant()) + " " + zoneName(from);
	}

	static String eventDay(JsonObject event)
	{
		Instant now = clock.instant();
		boolean started = "active".equals(str(event, "status"));
		Instant at = started ? eventEnd(event) : eventStart(event);
		if (at == null) return "";
		return (started ? "Ends " : "Starts ") + day(at.atZone(ZoneId.systemDefault()), now);
	}

	static String statusLabel(String status)
	{
		if ("active".equals(status)) return "Live";
		if ("ended".equals(status)) return "Ended";
		return "Upcoming";
	}

	static String eventTypeLabel(JsonObject event)
	{
		switch (str(event, "type"))
		{
			case "skill": return "Skill of the Week";
			case "boss": return "Boss of the Week";
			case "drop-party": return "Custom";
			default: return "Bingo";
		}
	}

	static JsonObject eventConfig(JsonObject event)
	{
		return object(event, "config");
	}

	static String taskTypeLabel(JsonObject task)
	{
		String type = str(task, "type");
		JsonObject config = eventConfig(task);
		switch (type)
		{
			case "kill": return "Boss KC";
			case "raid": return "Raid";
			case "xp": return "XP";
			case "drop":
				if (bool(config, "requireAllItems") || array(config, "itemGroups").size() > 0) return "Item set";
				String group = str(config, "itemGroup");
				return "jar".equals(group) ? "Any jar" : "pet".equals(group) ? "Any pet" : "Drop";
			default: return type.isEmpty() ? "Task" : Character.toUpperCase(type.charAt(0)) + type.substring(1);
		}
	}

	static JsonObject scoreFor(JsonArray scores, String teamId)
	{
		for (JsonObject score : objects(scores)) if (str(score, "teamId").equals(teamId)) return score;
		JsonObject empty = new JsonObject();
		empty.addProperty("points", 0);
		empty.addProperty("completedTasks", 0);
		empty.add("tasks", new JsonArray());
		return empty;
	}

	static List<JsonObject> rankedTeams(JsonObject event)
	{
		JsonArray scores = array(event, "teamScores");
		List<JsonObject> ranked = objects(array(event, "teams"));
		ranked.sort(Comparator
			.comparingInt((JsonObject team) -> integer(scoreFor(scores, str(team, "id")), "points", 0)).reversed()
			.thenComparing(Comparator.comparingInt((JsonObject team) -> integer(scoreFor(scores, str(team, "id")), "completedTasks", 0)).reversed())
			.thenComparing(team -> str(team, "name"), String.CASE_INSENSITIVE_ORDER));
		return ranked;
	}

	static JsonObject progressFor(JsonArray progressRows, String taskId)
	{
		for (JsonObject progress : objects(progressRows)) if (str(progress, "taskId").equals(taskId)) return progress;
		JsonObject empty = new JsonObject();
		empty.addProperty("progress", 0);
		empty.addProperty("target", 1);
		empty.addProperty("pending", false);
		empty.addProperty("completed", false);
		empty.add("completedBy", JsonNull.INSTANCE);
		return empty;
	}

	static String teamIdFor(JsonObject event, String displayName)
	{
		for (JsonObject member : objects(array(event, "members")))
		{
			if (samePlayer(str(member, "displayName"), displayName) && !str(member, "teamId").isEmpty()) return str(member, "teamId");
		}
		return "";
	}
}

package com.tsghub;

import java.math.BigDecimal;
import java.net.ConnectException;
import java.net.SocketTimeoutException;
import java.net.UnknownHostException;
import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import java.util.Locale;
import java.util.concurrent.CompletionException;
import lombok.extern.slf4j.Slf4j;

@Slf4j
final class TsgHubFormat
{
	static final DateTimeFormatter DATE_WITH_YEAR = DateTimeFormatter.ofPattern("d MMM yyyy", Locale.US);
	static final DateTimeFormatter SHORT_DATE = DateTimeFormatter.ofPattern("d MMM", Locale.US);
	static final DateTimeFormatter DAY = DateTimeFormatter.ofPattern("EEE d MMM", Locale.US);
	static final DateTimeFormatter CLOCK_24 = DateTimeFormatter.ofPattern("HH:mm", Locale.US);
	private static final DateTimeFormatter DAY_WITH_YEAR = DateTimeFormatter.ofPattern("EEE d MMM yyyy", Locale.US);
	private static final DateTimeFormatter HOUR = DateTimeFormatter.ofPattern("h", Locale.US);
	private static final DateTimeFormatter HOUR_MINUTE = DateTimeFormatter.ofPattern("h:mm", Locale.US);
	private static final DateTimeFormatter ZONE = DateTimeFormatter.ofPattern("zzz", Locale.US);
	static Clock clock = Clock.systemUTC();

	private TsgHubFormat()
	{
	}

	static String number(long value)
	{
		return String.format(Locale.US, "%,d", value);
	}

	static String elapsed(Instant then, Instant now)
	{
		long minutes = Math.max(0, Duration.between(then, now).toMinutes());
		if (minutes < 1) return "";
		if (minutes < 60) return minutes + "m";
		long hours = minutes / 60;
		if (hours < 24) return hours + "h";
		long days = hours / 24;
		if (days < 14) return days + "d";
		if (days < 60) return days / 7 + "w";
		if (days < 365) return days / 30 + "mo";
		return days / 365 + "y";
	}

	static String ago(Instant then, Instant now)
	{
		String elapsed = elapsed(then, now);
		return elapsed.isEmpty() ? "just now" : elapsed + " ago";
	}

	static String friendlyError(Throwable error)
	{
		if (error instanceof CompletionException && error.getCause() != null) error = error.getCause();
		log.warn("TSG Hub error", error);
		Throwable root = error;
		while (root.getCause() != null && root.getCause() != root) root = root.getCause();
		if (root instanceof ConnectException || root instanceof UnknownHostException)
			return "Can't reach the TSG Hub service. Try again in a moment.";
		if (root instanceof SocketTimeoutException)
			return "The TSG Hub service took too long to respond. Try again.";
		String message = error.getMessage();
		if (message == null || message.trim().isEmpty()) return "Something went wrong (" + root.getClass().getSimpleName() + "). Details are in the RuneLite log.";
		return message.endsWith(".") ? message : message + ".";
	}

	static String plural(int count, String noun)
	{
		return count + " " + noun + (count == 1 ? "" : "s");
	}

	static String zoneName(ZonedDateTime time)
	{
		return time.format(ZONE);
	}

	static String zoneLabel(ZoneId zone, Instant now)
	{
		String name = zoneName(now.atZone(zone));
		return name.equals(zone.getId()) ? name : name + " (" + zone.getId() + ")";
	}

	static String shortDate(String iso, Instant now, ZoneId zone)
	{
		Instant at = TsgHubJson.instant(iso);
		if (at == null) return "";
		ZonedDateTime day = at.atZone(zone);
		return day.format(day.getYear() == now.atZone(zone).getYear() ? SHORT_DATE : DATE_WITH_YEAR);
	}

	static String localDate(Instant when, ZoneId zone)
	{
		return when.atZone(zone).format(DATE_WITH_YEAR);
	}

	private static String clock(ZonedDateTime time, boolean meridiem)
	{
		String text = time.format(time.getMinute() == 0 ? HOUR : HOUR_MINUTE);
		return meridiem ? text + (time.getHour() < 12 ? "am" : "pm") : text;
	}

	static String day(ZonedDateTime time, Instant now)
	{
		return time.format(time.getYear() == now.atZone(time.getZone()).getYear() ? DAY : DAY_WITH_YEAR);
	}

	static String when(ZonedDateTime time, Instant now)
	{
		return day(time, now) + ", " + clock(time, true);
	}

	static String timeRange(Instant start, Instant end, ZoneId zone, Instant now)
	{
		if (start == null) return "Time TBD";
		ZonedDateTime from = start.atZone(zone);
		if (end == null) return when(from, now) + " " + zoneName(from);
		ZonedDateTime to = end.atZone(zone);
		boolean sameZone = zoneName(from).equals(zoneName(to));
		boolean sameDay = from.toLocalDate().equals(to.toLocalDate());
		if (sameDay && sameZone)
			return day(from, now) + ", " + clock(from, from.getHour() < 12 != to.getHour() < 12) + "-" + clock(to, true) + " " + zoneName(to);
		String until = sameDay ? clock(to, true) : when(to, now);
		return when(from, now) + (sameZone ? "" : " " + zoneName(from)) + " to " + until + " " + zoneName(to);
	}

	static String span(Duration duration)
	{
		long minutes = Math.max(1, (duration.getSeconds() + 59) / 60);
		long days = minutes / 1440, hours = minutes % 1440 / 60, rest = minutes % 60;
		if (days > 0) return days + "d" + (hours > 0 ? " " + hours + "h" : "");
		if (hours > 0) return hours + "h" + (rest > 0 ? " " + rest + "m" : "");
		return rest + "m";
	}

	static String relativeTime(Instant start, Instant end, Instant now)
	{
		if (start == null) return "";
		if (now.isBefore(start)) return "starts in " + span(Duration.between(now, start));
		if (end == null) return "happening now";
		if (now.isBefore(end)) return "ends in " + span(Duration.between(now, end));
		return "ended";
	}

	static String capitalize(String text)
	{
		return text.isEmpty() ? text : Character.toUpperCase(text.charAt(0)) + text.substring(1);
	}

	static String place(int place)
	{
		if (place % 100 >= 11 && place % 100 <= 13) return place + "th";
		switch (place % 10)
		{
			case 1: return place + "st";
			case 2: return place + "nd";
			case 3: return place + "rd";
			default: return place + "th";
		}
	}

	static long parseMillions(String text)
	{
		String value = text.trim().replace(",", "");
		if (value.isEmpty()) return 0;
		try
		{
			BigDecimal amount = new BigDecimal(value).multiply(BigDecimal.valueOf(1_000_000L));
			if (amount.signum() <= 0 || amount.stripTrailingZeros().scale() > 0) return -1;
			return amount.longValueExact();
		}
		catch (NumberFormatException | ArithmeticException e)
		{
			return -1;
		}
	}

	static String millions(long gp)
	{
		return BigDecimal.valueOf(gp).divide(BigDecimal.valueOf(1_000_000L)).stripTrailingZeros().toPlainString();
	}

	static String formatGp(long value)
	{
		if (value <= 0) return "";
		if (value >= 1_000_000_000L) return trimDecimal(value / 1_000_000_000.0) + "B";
		if (value >= 1_000_000L) return trimDecimal(value / 1_000_000.0) + "M";
		if (value >= 1_000L) return trimDecimal(value / 1_000.0) + "K";
		return value + " gp";
	}

	private static String trimDecimal(double value)
	{
		String text = String.format(Locale.ROOT, "%.1f", Math.floor(value * 10) / 10);
		return text.endsWith(".0") ? text.substring(0, text.length() - 2) : text;
	}
	static String skillName(String key)
	{
		if (key == null || key.isEmpty()) return "";
		String lower = key.toLowerCase(Locale.ROOT).replace('_', ' ');
		return Character.toUpperCase(lower.charAt(0)) + lower.substring(1);
	}
}

package com.tsghub;

import static com.tsghub.TsgHubJson.*;
import static com.tsghub.TsgHubSession.GROUP_PASSPHRASE;
import static com.tsghub.TsgHubSession.GROUP_PLAYER;
import static com.tsghub.TsgHubSession.GROUP_TOKEN;
import static com.tsghub.TsgHubUi.*;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.tsghub.TsgHubUi.Tone;
import com.tsghub.group.GroupTracker;
import com.tsghub.group.data.PartyPlayer;
import java.util.AbstractMap;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.Supplier;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.party.PartyService;

final class TsgHubGroups implements GroupTracker.Listener
{
	private static final String WILDERNESS = "Wilderness lvl ";
	// The service drops members after 3 minutes without a check-in.
	static final int HEARTBEAT_SECONDS = 60;
	static final int REFRESH_SECONDS = 30;

	private final TsgHubPlugin plugin;
	private final Client client;
	private final PartyService partyService;
	private final ScheduledExecutorService executor;
	private final Supplier<TsgHubApi> api;
	private final Supplier<TsgHubSidebarPanel> sidebar;
	private final TsgHubSocket socket;
	private volatile GroupTracker tracker;
	private volatile JsonObject group;
	private volatile boolean awaitingBeat;

	TsgHubGroups(TsgHubPlugin plugin, Client client, PartyService partyService, ScheduledExecutorService executor,
		Supplier<TsgHubApi> api, Supplier<TsgHubSidebarPanel> sidebar, TsgHubSocket socket)
	{
		this.plugin = plugin;
		this.socket = socket;
		this.client = client;
		this.partyService = partyService;
		this.executor = executor;
		this.api = api;
		this.sidebar = sidebar;
	}

	void setTracker(GroupTracker tracker)
	{
		this.tracker = tracker;
	}

	boolean isGroupParty(String passphrase)
	{
		String saved = plugin.session().get(GROUP_PASSPHRASE);
		return plugin.sharingEnabled() && passphrase != null && !saved.isEmpty() && saved.equals(passphrase);
	}

	boolean inGroup()
	{
		return !plugin.session().get(GROUP_TOKEN).isEmpty();
	}

	JsonObject currentGroup()
	{
		return group;
	}

	boolean isLeader()
	{
		JsonObject current = group;
		return inGroup() && current != null && PlayerNames.samePlayer(TsgHubJson.str(current, "leaderName"), plugin.session().get(GROUP_PLAYER));
	}

	boolean inOtherParty()
	{
		return partyService.isInParty() && !isGroupParty(partyService.getPartyPassphrase());
	}

	void loadGroups()
	{
		loadGroups(false);
	}

	private void loadGroups(boolean quiet)
	{
		if (!plugin.canUseHub() || executor.isShutdown()) return;
		String clan = TsgHubApi.encode(plugin.getDetectedClanName());
		if (!quiet) busy(true);
		api.get().call("GET", "/v1/groups?clanName=" + clan, null, null).whenCompleteAsync((response, error) -> {
			try
			{
				apply(TsgHubApi.result(response, error).getAsJsonArray("groups"));
			}
			catch (Exception e) { if (!quiet) status("Couldn't load parties. " + TsgHubFormat.friendlyError(e), Tone.ERROR); }
			finally { if (!quiet) busy(false); }
		}, executor);
	}

	void apply(JsonArray groups)
	{
		if (groups == null) return;
		JsonObject current = group;
		if (current != null && inGroup())
		{
			JsonObject next = TsgHubJson.byId(groups, TsgHubJson.str(current, "id"));
			if (next != null) group = next;
			if ((next == null || !memberNames(next).equals(memberNames(current))) && !executor.isShutdown()) executor.submit(this::heartbeat);
		}
		plugin.ui(s -> s.setGroups(groups));
	}

	void refresh()
	{
		if (inGroup() && !executor.isShutdown()) executor.submit(this::heartbeat);
		loadGroups();
	}

	void create()
	{
		if (!plugin.canUseHub()) { plugin.ui(s -> s.groupActionFailed("Log in to a " + plugin.getHubClanName() + " character first.")); return; }
		enter("POST", "/v1/groups", identity(), true);
	}

	void setTitle(String title)
	{
		JsonObject payload = new JsonObject();
		payload.addProperty("activity", title.trim());
		update("/v1/groups/title", payload);
	}

	void kick(String name)
	{
		JsonObject payload = new JsonObject();
		payload.addProperty("displayName", name);
		update("/v1/groups/kick", payload);
		if (!executor.isShutdown()) executor.submit(this::heartbeat);
	}

	void setLocked(boolean locked)
	{
		JsonObject payload = new JsonObject();
		payload.addProperty("locked", locked);
		update("/v1/groups/lock", payload);
	}

	private void update(String path, JsonObject payload)
	{
		String token = plugin.session().get(GROUP_TOKEN);
		if (token.isEmpty() || executor.isShutdown()) return;
		api.get().call("POST", path, token, payload).whenCompleteAsync((response, error) -> {
			try
			{
				JsonObject joined = TsgHubApi.result(response, error).getAsJsonObject("group");
				group = joined;
				plugin.ui(s -> s.groupRefreshed(joined));
				refreshUnlessLive();
			}
			catch (TsgHubApi.HttpError e) { when404(e); }
			catch (Exception e) { plugin.ui(s -> s.groupActionFailed(TsgHubFormat.friendlyError(e))); }
		}, executor);
	}

	void join(String groupId)
	{
		if (!plugin.canUseHub()) { plugin.ui(s -> s.groupActionFailed("Log in to a " + plugin.getHubClanName() + " character first.")); return; }
		enter("POST", "/v1/groups/" + groupId + "/join", identity(), false);
	}

	private void enter(String method, String path, JsonObject payload, boolean created)
	{
		String previousToken = plugin.session().get(GROUP_TOKEN);
		api.get().call(method, path, null, payload).whenCompleteAsync((response, error) -> {
			try
			{
				JsonObject result = TsgHubApi.result(response, error);
				JsonObject joined = result.getAsJsonObject("group");
				String passphrase = result.get("passphrase").getAsString();
				// The service already removed us from the previous group.
				if (!previousToken.isEmpty()) forget();
				// Save before switching so the tracker recognises the new party.
				plugin.session().set(GROUP_TOKEN, result.get("token").getAsString());
				plugin.session().set(GROUP_PASSPHRASE, passphrase);
				plugin.session().set(GROUP_PLAYER, plugin.getDetectedPlayerName());
				group = joined;
				partyService.changeParty(passphrase);
				status(created ? "Started a party." : "Joined " + partyTitle(joined) + ".", Tone.SUCCESS);
				plugin.ui(s -> s.showGroup(joined));
				refreshUnlessLive();
			}
			catch (TsgHubApi.HttpError e) { when404(e); }
			catch (Exception e) { plugin.ui(s -> s.groupActionFailed(TsgHubFormat.friendlyError(e))); }
		}, executor);
	}

	void leave()
	{
		String token = plugin.session().get(GROUP_TOKEN);
		// Compare passphrases directly: sharing may already be off.
		String passphrase = plugin.session().get(GROUP_PASSPHRASE);
		boolean ours = partyService.isInParty() && !passphrase.isEmpty() && passphrase.equals(partyService.getPartyPassphrase());
		forget();
		if (ours) partyService.changeParty(null);
		plugin.ui(TsgHubSidebarPanel::showGroupList);
		if (token.isEmpty() || executor.isShutdown()) return;
		// The service drops idle members on its own if this fails.
		api.get().call("POST", "/v1/groups/leave", token, null).whenCompleteAsync((response, error) -> refreshUnlessLive(), executor);
	}

	void heartbeat()
	{
		String token = plugin.session().get(GROUP_TOKEN);
		if (token.isEmpty()) return;
		if (!plugin.sharingEnabled()) { leave(); return; }
		GroupTracker t = tracker;
		if (t != null && t.idleTooLong()) { status("Left your party after 30 minutes logged out.", Tone.INFO); leave(); return; }
		String name = plugin.getDetectedPlayerName();
		if (!name.isEmpty() && !PlayerNames.samePlayer(name, plugin.session().get(GROUP_PLAYER))) { leave(); return; }
		JsonObject payload = new JsonObject();
		if (client.getGameState() == GameState.LOGGED_IN) payload.addProperty("world", client.getWorld());
		payload.addProperty("area", plugin.currentArea());
		if (!awaitingBeat && socket.groupHeartbeat(token, payload))
		{
			awaitingBeat = true;
			return;
		}
		awaitingBeat = false;
		api.get().call("POST", "/v1/groups/heartbeat", token, payload).whenCompleteAsync((response, error) -> {
			try { beaten(TsgHubApi.result(response, error)); }
			catch (TsgHubApi.HttpError e) { beatRejected(e.status); }
			catch (Exception ignored) { /* Try again next beat. */ }
		}, executor);
	}

	void beaten(JsonObject result)
	{
		awaitingBeat = false;
		if (!inGroup() || !result.has("group") || !result.get("group").isJsonObject()) return;
		JsonObject joined = result.getAsJsonObject("group");
		group = joined;
		String rotated = str(result, "passphrase");
		if (!rotated.isEmpty()) plugin.session().set(GROUP_PASSPHRASE, rotated);
		// Still listed after a client restart but not connected.
		String passphrase = plugin.session().get(GROUP_PASSPHRASE);
		if (!passphrase.equals(partyService.getPartyPassphrase())) partyService.changeParty(passphrase);
		plugin.ui(s -> s.groupRefreshed(joined));
	}

	void beatRejected(int status)
	{
		awaitingBeat = false;
		if (status != 404 || !inGroup()) return;
		status("Your party has closed.", Tone.INFO);
		leave();
	}

	private void refreshUnlessLive()
	{
		if (!socket.isLive()) loadGroups(true);
	}

	private static List<String> memberNames(JsonObject group)
	{
		List<String> names = new ArrayList<>();
		for (JsonObject member : objects(array(group, "members"))) names.add(PlayerNames.key(str(member, "displayName")));
		return names;
	}

	private void when404(TsgHubApi.HttpError e)
	{
		if (e.status == 404) loadGroups();
		plugin.ui(s -> s.groupActionFailed(TsgHubFormat.friendlyError(e)));
	}

	void onSharingDisabled()
	{
		if (inGroup()) leave();
	}

	private void forget()
	{
		group = null;
		plugin.session().set(GROUP_TOKEN, "");
		plugin.session().set(GROUP_PASSPHRASE, "");
		plugin.session().set(GROUP_PLAYER, "");
	}

	@Override
	public void memberUpdated(PartyPlayer player, boolean self)
	{
		TsgHubSidebarPanel s = sidebar.get();
		if (s != null) s.groupMemberUpdated(player, self);
	}

	@Override
	public void memberRemoved(PartyPlayer player)
	{
		TsgHubSidebarPanel s = sidebar.get();
		if (s != null) s.groupMemberRemoved(player);
	}

	List<String> liveAreas()
	{
		GroupTracker t = tracker;
		return t == null ? java.util.Collections.emptyList() : t.areas();
	}

	void autoRefresh()
	{
		TsgHubSidebarPanel s = sidebar.get();
		if (s != null && s.wantsGroups()) loadGroups(true);
	}

	@Override
	public void areasChanged()
	{
		TsgHubSidebarPanel s = sidebar.get();
		if (s != null) s.partyAreasChanged();
	}

	@Override
	public void membersCleared()
	{
		TsgHubSidebarPanel s = sidebar.get();
		if (s != null) s.groupMembersCleared();
	}

	@Override
	public void partyChanged(String passphrase)
	{
		// Switching parties elsewhere also leaves the group.
		if (inGroup() && !isGroupParty(passphrase)) executor.submit(this::leave);
	}

	private JsonObject identity()
	{
		JsonObject payload = new JsonObject();
		payload.addProperty("displayName", plugin.getDetectedPlayerName());
		payload.addProperty("clanName", plugin.getDetectedClanName());
		payload.addProperty("world", client.getWorld());
		payload.addProperty("area", plugin.currentArea());
		return payload;
	}

	private void status(String message, Tone tone)
	{
		plugin.ui(s -> s.setStatus(message, tone));
	}

	private void busy(boolean isBusy)
	{
		plugin.ui(s -> s.setBusy(isBusy));
	}

	static String partyTitle(JsonObject group)
	{
		String title = str(group, "activity");
		if (!title.isEmpty()) return title;
		Map.Entry<String, Integer> area = areaSummary(array(group, "members"));
		if (area != null) return area.getKey();
		String leader = str(group, "leaderName");
		return leader.isEmpty() ? "Party" : leader + "'s party";
	}

	static Map.Entry<String, Integer> areaSummary(JsonArray members)
	{
		List<String> areas = new ArrayList<>();
		for (JsonObject member : objects(members)) areas.add(str(member, "area"));
		return areaSummary(areas);
	}

	static Map.Entry<String, Integer> areaSummary(List<String> areas)
	{
		Map<String, Integer> counts = new LinkedHashMap<>();
		int low = Integer.MAX_VALUE;
		int high = 0;
		for (String area : areas)
		{
			if (area == null || area.isEmpty()) continue;
			if (area.startsWith(WILDERNESS))
			{
				try
				{
					int level = Integer.parseInt(area.substring(WILDERNESS.length()).trim());
					low = Math.min(low, level);
					high = Math.max(high, level);
					area = "Wilderness";
				}
				catch (NumberFormatException ignored) { }
			}
			counts.merge(area, 1, Integer::sum);
		}
		if (counts.isEmpty()) return null;
		Map.Entry<String, Integer> top = Collections.max(counts.entrySet(), Map.Entry.comparingByValue());
		String name = top.getKey();
		if (name.equals("Wilderness") && high > 0) name += " lvl " + (low == high ? String.valueOf(low) : low + "-" + high);
		return new AbstractMap.SimpleImmutableEntry<>(name, top.getValue());
	}
}

package com.tsghub;

import static com.tsghub.TsgHubHtml.*;
import static com.tsghub.TsgHubTheme.*;
import static com.tsghub.TsgHubUi.*;

import com.tsghub.group.ui.skills.PlayerSkillsPanel;
import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import javax.swing.BorderFactory;
import javax.swing.ImageIcon;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import net.runelite.api.Experience;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.hiscore.HiscoreEndpoint;
import net.runelite.client.hiscore.HiscoreResult;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.hiscore.HiscoreSkillType;
import net.runelite.client.hiscore.Skill;
import net.runelite.client.util.ImageUtil;

final class TsgHubHiscores
{
	static final List<HiscoreSkill> SKILL_GRID = PlayerSkillsPanel.SKILL_ORDER.stream()
		.map(skill -> HiscoreSkill.valueOf(skill.name()))
		.collect(Collectors.toList());
	private static final int ICON = 16;
	private static final Map<HiscoreSkill, BufferedImage> SKILL_ICONS = new EnumMap<>(HiscoreSkill.class);

	private TsgHubHiscores()
	{
	}

	static HiscoreEndpoint endpoint(int accountType)
	{
		switch (accountType)
		{
			case 1: return HiscoreEndpoint.IRONMAN;
			case 2: return HiscoreEndpoint.ULTIMATE_IRONMAN;
			case 3: return HiscoreEndpoint.HARDCORE_IRONMAN;
			default: return HiscoreEndpoint.NORMAL;
		}
	}

	static int level(HiscoreResult result, HiscoreSkill skill)
	{
		Skill entry = result.getSkill(skill);
		return entry == null ? -1 : entry.getLevel();
	}

	static int combatLevel(HiscoreResult result)
	{
		return Experience.getCombatLevel(
			Math.max(1, level(result, HiscoreSkill.ATTACK)),
			Math.max(1, level(result, HiscoreSkill.STRENGTH)),
			Math.max(1, level(result, HiscoreSkill.DEFENCE)),
			Math.max(10, level(result, HiscoreSkill.HITPOINTS)),
			Math.max(1, level(result, HiscoreSkill.MAGIC)),
			Math.max(1, level(result, HiscoreSkill.RANGED)),
			Math.max(1, level(result, HiscoreSkill.PRAYER)));
	}

	static List<HiscoreSkill> scored(HiscoreResult result, HiscoreSkillType type)
	{
		List<HiscoreSkill> out = new ArrayList<>();
		for (HiscoreSkill skill : HiscoreSkill.values())
			if (skill.getType() == type && level(result, skill) > 0) out.add(skill);
		out.sort(Comparator.comparing(TsgHubHiscores::sortName, String.CASE_INSENSITIVE_ORDER));
		return out;
	}

	private static String sortName(HiscoreSkill skill)
	{
		String name = skill.getName();
		return name.regionMatches(true, 0, "The ", 0, 4) ? name.substring(4) : name;
	}

	static String subtitle(HiscoreResult result)
	{
		int total = level(result, HiscoreSkill.OVERALL);
		return "Combat " + combatLevel(result) + (total > 0 ? " · Total " + TsgHubFormat.number(total) : "");
	}

	static JPanel skillGrid(HiscoreResult result)
	{
		JPanel grid = new JPanel(new GridLayout(0, 3, GAP_XS, GAP_XS));
		grid.setOpaque(false);
		grid.setAlignmentX(0f);
		for (HiscoreSkill skill : SKILL_GRID) grid.add(skillCell(result, skill));
		return fitHeight(grid);
	}

	private static JPanel skillCell(HiscoreResult result, HiscoreSkill skill)
	{
		JPanel cell = card();
		cell.setBorder(BorderFactory.createEmptyBorder(4, 6, 4, 6));
		int level = level(result, skill);
		JLabel label = label(level > 0 ? String.valueOf(level) : "--", level >= 99 ? WARNING : TEXT, boldFont());
		label.setIcon(skillIcon(skill));
		label.setIconTextGap(6);
		cell.add(label, BorderLayout.CENTER);
		cell.setToolTipText(skillTip(result.getSkill(skill), skill.getName()));
		return cell;
	}

	static JPanel totalRow(HiscoreResult result)
	{
		JPanel row = card();
		Skill overall = result.getSkill(HiscoreSkill.OVERALL);
		int total = overall == null ? -1 : overall.getLevel();
		JLabel left = label("Total " + (total > 0 ? TsgHubFormat.number(total) : "--"), TEXT, boldFont());
		left.setIcon(skillIcon(HiscoreSkill.OVERALL));
		left.setIconTextGap(6);
		row.add(left, BorderLayout.CENTER);
		if (overall != null && overall.getExperience() > 0)
			row.add(label(TsgHubFormat.number(overall.getExperience()) + " xp", MUTED, smallFont()), BorderLayout.EAST);
		row.setToolTipText(skillTip(overall, "Overall"));
		return fitHeight(row);
	}

	static JPanel scoreRow(HiscoreResult result, HiscoreSkill skill, SpriteManager sprites)
	{
		JPanel row = card();
		row.setBorder(BorderFactory.createEmptyBorder(3, 7, 3, 7));
		JLabel name = shrinkable(label(skill.getName(), TEXT, smallFont()));
		JLabel icon = new JLabel();
		icon.setPreferredSize(new Dimension(ICON, ICON));
		icon.setHorizontalAlignment(SwingConstants.CENTER);
		if (skill.getSpriteId() > 0)
		{
			sprites.getSpriteAsync(skill.getSpriteId(), 0, sprite -> SwingUtilities.invokeLater(() ->
				icon.setIcon(new ImageIcon(ImageUtil.resizeImage(ImageUtil.resizeCanvas(sprite, 25, 25), ICON, ICON)))));
		}
		row.add(icon, BorderLayout.WEST);
		row.add(name, BorderLayout.CENTER);
		row.add(label(TsgHubFormat.number(level(result, skill)), ACCENT, smallFont()), BorderLayout.EAST);
		row.setToolTipText(skillTip(result.getSkill(skill), skill.getName()));
		return fitHeight(row);
	}

	private static String skillTip(Skill skill, String name)
	{
		if (skill == null || skill.getRank() <= 0) return "<html><b>" + escape(name) + "</b><br>Not ranked</html>";
		String detail = skill.getExperience() >= 0 ? "XP: " + TsgHubFormat.number(skill.getExperience()) + "<br>" : "";
		return "<html><b>" + escape(name) + "</b><br>" + detail + "Rank: " + TsgHubFormat.number(skill.getRank()) + "</html>";
	}

	private static synchronized ImageIcon skillIcon(HiscoreSkill skill)
	{
		BufferedImage image = SKILL_ICONS.computeIfAbsent(skill, s -> ImageUtil.loadImageResource(TsgHubHiscores.class, "/skill_icons_small/" + s.name().toLowerCase() + ".png"));
		return image == null ? null : new ImageIcon(image);
	}
}

package com.tsghub;

import static com.tsghub.PlayerNames.*;
import static com.tsghub.TsgHubTheme.*;
import static com.tsghub.TsgHubUi.*;
import static net.runelite.client.util.ColorUtil.toHexColor;

import java.awt.Color;
import javax.swing.text.html.HTML;

final class TsgHubHtml
{
	private TsgHubHtml()
	{
	}

	static String escape(String text)
	{
		return text == null ? "" : text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	// Swing HTML treats px as 1/72in but fonts render at 96dpi, so scale by 3/4.
	static String html(String innerHtml, int widthPx)
	{
		return "<html><body style='width:" + Math.round(widthPx * 0.75f) + "px'>" + innerHtml + "</body></html>";
	}

	private static final java.util.regex.Pattern URL = java.util.regex.Pattern.compile("https?://[^\\s<>\"']+");

	private static final int LINK_TEXT_MAX = 24;
	private static final java.util.regex.Pattern BULLET = java.util.regex.Pattern.compile("[-*•]\\s+(.+)");
	private static final java.util.regex.Pattern NUMBERED = java.util.regex.Pattern.compile("\\d{1,2}[.)]\\s+(.+)");
	private static final java.util.regex.Pattern HEADING = java.util.regex.Pattern.compile("(#{1,3})\\s+(.+)");
	private static final java.util.regex.Pattern RULE = java.util.regex.Pattern.compile("-{3,}|\\*{3,}|_{3,}");
	private static final java.util.regex.Pattern LINK = java.util.regex.Pattern.compile("\\[([^\\]]+)]\\((https?://[^\\s)]+)\\)|(https?://[^\\s<>\"']+)");
	private static final java.util.regex.Pattern LEAD_IN = java.util.regex.Pattern.compile("([^:/]{1,24}:)(\\s.*)");

	// Escapes plain text for HTML, keeps line breaks, and turns http(s) URLs into links. Long URLs show
	// shortened: Swing can't wrap inside one, and a long one widens the whole label past its wrap width.
	static String linkify(String text)
	{
		String raw = text == null ? "" : text;
		StringBuilder out = new StringBuilder();
		java.util.regex.Matcher matcher = URL.matcher(raw);
		int last = 0;
		while (matcher.find())
		{
			String url = matcher.group().replaceAll("[.,;:!?)]+$", "");
			out.append(escape(raw.substring(last, matcher.start())));
			out.append("<a href='").append(escape(url)).append("' style='color:").append(toHexColor(ACCENT)).append("'>")
				.append(escape(linkText(url))).append("</a>");
			last = matcher.start() + url.length();
		}
		out.append(escape(raw.substring(last)));
		return out.toString().replace("\n", "<br>");
	}

	static String postHtml(String text)
	{
		StringBuilder out = new StringBuilder();
		StringBuilder block = new StringBuilder();
		String kind = "";
		for (String line : (text == null ? "" : text).split("\n", -1))
		{
			String trimmed = line.trim();
			java.util.regex.Matcher bullet = BULLET.matcher(trimmed);
			java.util.regex.Matcher numbered = NUMBERED.matcher(trimmed);
			java.util.regex.Matcher heading = HEADING.matcher(trimmed);
			String next = trimmed.isEmpty() || heading.matches() || RULE.matcher(trimmed).matches() ? ""
				: bullet.matches() ? "ul" : numbered.matches() ? "ol" : trimmed.startsWith(">") ? "quote" : "p";
			if (!next.equals(kind)) flushBlock(out, block, kind);
			kind = next;
			if (heading.matches())
			{
				boolean big = heading.group(1).length() == 1;
				int top = out.length() == 0 ? 0 : 6;
				out.append("<p style='margin:0;margin-top:").append(top).append("px'>").append(big ? "<font size='+1'>" : "").append("<b>")
					.append(inline(heading.group(2))).append("</b>").append(big ? "</font>" : "").append("</p>");
			}
			else if (RULE.matcher(trimmed).matches()) out.append("<p style='margin:0;margin-top:6px;border-top:1px solid ").append(toHexColor(MUTED.darker())).append("'></p>");
			else if (next.equals("ul")) block.append("<li>").append(leadIn(bullet.group(1))).append("</li>");
			else if (next.equals("ol")) block.append("<li>").append(leadIn(numbered.group(1))).append("</li>");
			else if (!next.isEmpty())
			{
				if (block.length() > 0) block.append("<br>");
				block.append(inline(next.equals("quote") ? trimmed.substring(1).trim() : trimmed));
			}
		}
		flushBlock(out, block, kind);
		return out.toString();
	}

	private static void flushBlock(StringBuilder out, StringBuilder block, String kind)
	{
		if (block.length() == 0) return;
		String top = "margin-top:" + (out.length() == 0 ? 0 : 4) + "px";
		if (kind.equals("ul") || kind.equals("ol"))
			out.append("<").append(kind).append(" style='margin-left:").append(kind.equals("ol") ? 16 : 10).append("px;margin-bottom:0;").append(top).append("'>")
				.append(block).append("</").append(kind).append(">");
		else if (kind.equals("quote"))
			out.append("<p style='margin:0;").append(top).append(";margin-left:4px;padding-left:6px;border-left:2px solid ").append(toHexColor(MUTED))
				.append(";color:").append(toHexColor(MUTED)).append("'>").append(block).append("</p>");
		else out.append("<p style='margin:0;").append(top).append("'>").append(block).append("</p>");
		block.setLength(0);
	}

	private static String leadIn(String item)
	{
		java.util.regex.Matcher lead = LEAD_IN.matcher(item);
		return lead.matches() ? "<b>" + inline(lead.group(1)) + "</b>" + inline(lead.group(2)) : inline(item);
	}

	private static String inline(String raw)
	{
		StringBuilder out = new StringBuilder();
		java.util.regex.Matcher matcher = LINK.matcher(raw);
		int last = 0;
		while (matcher.find())
		{
			String url = matcher.group(2) != null ? matcher.group(2) : matcher.group(3).replaceAll("[.,;:!?)]+$", "");
			String shown = matcher.group(1) != null ? emphasis(escape(matcher.group(1))) : escape(linkText(url));
			out.append(emphasis(escape(raw.substring(last, matcher.start()))));
			out.append("<a href='").append(escape(url)).append("' style='color:").append(toHexColor(ACCENT)).append("'>").append(shown).append("</a>");
			last = matcher.group(2) != null ? matcher.end() : matcher.start() + url.length();
		}
		return out.append(emphasis(escape(raw.substring(last)))).toString();
	}

	private static String emphasis(String text)
	{
		return text.replaceAll("\\*\\*(?=\\S)(.+?)(?<=\\S)\\*\\*", "<b>$1</b>")
			.replaceAll("__(?=\\S)(.+?)(?<=\\S)__", "<u>$1</u>")
			.replaceAll("~~(?=\\S)(.+?)(?<=\\S)~~", "<strike>$1</strike>")
			.replaceAll("(?<![*\\w])\\*(?=\\S)(.+?)(?<=\\S)\\*(?![*\\w])", "<i>$1</i>")
			.replaceAll("(?<![_\\w])_(?=\\S)(.+?)(?<=\\S)_(?![_\\w])", "<i>$1</i>");
	}

	static String linkText(String url)
	{
		String shown = url.replaceFirst("^https?://(www\\.)?", "").replaceAll("/$", "");
		return shown.length() > LINK_TEXT_MAX ? shown.substring(0, LINK_TEXT_MAX - 3) + "..." : shown;
	}

	static String nameHtml(String name, String self)
	{
		return samePlayer(name, self) ? selfName(escape(name)) : escape(name);
	}

	static String tipSection(boolean first, String heading)
	{
		return "<div style='margin-top:" + (first ? 0 : 6) + "px'>" + heading + "</div>";
	}

	static String tipCard(Color bar, String inner)
	{
		return "<table cellspacing='0' cellpadding='0' width='100%' style='margin-top:2px'><tr><td bgcolor='" + toHexColor(bar) + "' width='2'></td>"
			+ "<td bgcolor='" + toHexColor(CARD_HOVER) + "' style='padding:3px 6px'>" + inner + "</td></tr></table>";
	}

	static String tipLine(Color color, String html)
	{
		return "<font color='" + toHexColor(color) + "'>" + html + "</font>";
	}
}

package com.tsghub;

import static com.tsghub.TsgHubTheme.*;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Component;
import java.awt.Graphics2D;
import java.awt.Graphics;
import java.awt.RenderingHints;
import java.awt.geom.Area;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Line2D;
import java.awt.geom.Path2D;
import javax.swing.AbstractButton;
import javax.swing.Icon;
import javax.swing.Timer;

final class TsgHubIcons
{
	private TsgHubIcons()
	{
	}

	abstract static class HoverIcon implements Icon
	{
		private final int size;
		HoverIcon(int size) { this.size = size; }
		@Override public int getIconWidth() { return size; }
		@Override public int getIconHeight() { return size; }

		@Override
		public final void paintIcon(Component component, Graphics graphics, int x, int y)
		{
			Graphics2D g = (Graphics2D) graphics.create();
			g.translate(x, y);
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			boolean hovered = component instanceof AbstractButton && ((AbstractButton) component).getModel().isRollover();
			boolean enabled = component == null || component.isEnabled();
			g.setColor(!enabled ? BORDER : hovered ? hoverColor() : MUTED);
			g.setStroke(new BasicStroke(1.8f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			paint(g, component);
			g.dispose();
		}

		abstract void paint(Graphics2D g, Component component);

		Color hoverColor() { return ACCENT; }
	}

	static final class TrashIcon extends HoverIcon
	{
		TrashIcon() { super(16); }
		@Override Color hoverColor() { return ERROR; }
		@Override void paint(Graphics2D g, Component c)
		{
			g.setStroke(new BasicStroke(1.5f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.drawLine(2, 4, 14, 4);
			g.drawLine(6, 4, 6, 2);
			g.drawLine(6, 2, 10, 2);
			g.drawLine(10, 2, 10, 4);
			g.drawRect(4, 4, 8, 10);
			g.drawLine(7, 7, 7, 11);
			g.drawLine(9, 7, 9, 11);
		}
	}

	static final class BackIcon extends HoverIcon
	{
		BackIcon() { super(16); }
		@Override void paint(Graphics2D g, Component c)
		{
			g.drawLine(10, 3, 5, 8);
			g.drawLine(5, 8, 10, 13);
		}
	}

	static final class RefreshIcon extends HoverIcon
	{
		private float angle;
		private Timer timer;

		RefreshIcon() { super(16); }

		void setSpinning(boolean spinning, Component owner)
		{
			if (spinning)
			{
				if (timer == null)
				{
					timer = new Timer(30, e -> { angle = (angle + 18) % 360; owner.repaint(); });
				}
				if (!timer.isRunning()) timer.start();
			}
			else if (timer != null)
			{
				timer.stop();
				angle = 0;
				owner.repaint();
			}
		}

		@Override void paint(Graphics2D g, Component c)
		{
			g.rotate(Math.toRadians(angle), 8, 8);
			g.drawArc(2, 2, 12, 12, 48, 292);
			g.fillPolygon(new int[] {12, 16, 11}, new int[] {1, 5, 6}, 3);
		}
	}

	static final class OrganizerIcon extends HoverIcon
	{
		OrganizerIcon() { super(16); }
		@Override void paint(Graphics2D g, Component c)
		{
			g.setStroke(new BasicStroke(1.4f));
			g.drawRect(2, 2, 12, 12);
			g.drawLine(2, 6, 14, 6);
			g.drawLine(6, 6, 6, 14);
		}
	}

	static final class PinIcon extends HoverIcon
	{
		PinIcon() { super(16); }
		@Override void paint(Graphics2D g, Component c)
		{
			g.setStroke(new BasicStroke(1.5f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.drawLine(5, 2, 11, 2);
			g.drawLine(6, 2, 6, 7);
			g.drawLine(10, 2, 10, 7);
			g.drawLine(3, 10, 13, 10);
			g.drawLine(6, 7, 3, 10);
			g.drawLine(10, 7, 13, 10);
			g.drawLine(8, 10, 8, 15);
		}
	}

	abstract static class TileIcon implements Icon
	{
		@Override public int getIconWidth() { return 24; }
		@Override public int getIconHeight() { return 24; }

		@Override
		public final void paintIcon(Component component, Graphics graphics, int x, int y)
		{
			Graphics2D g = (Graphics2D) graphics.create();
			g.translate(x, y);
			g.scale(1.5, 1.5);
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setColor(ACCENT);
			g.setStroke(new BasicStroke(1.5f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			paint(g);
			g.dispose();
		}

		abstract void paint(Graphics2D g);
	}

	static final class CalendarIcon extends TileIcon
	{
		@Override void paint(Graphics2D g)
		{
			g.drawRoundRect(2, 3, 12, 11, 2, 2);
			g.drawLine(2, 7, 14, 7);
			g.drawLine(5, 1, 5, 4);
			g.drawLine(11, 1, 11, 4);
			g.fillRect(5, 9, 2, 2);
			g.fillRect(9, 9, 2, 2);
		}
	}

	static final class PartyIcon extends TileIcon
	{
		@Override void paint(Graphics2D g)
		{
			g.drawOval(3, 2, 5, 5);
			g.drawArc(0, 9, 11, 10, 0, 180);
			g.drawOval(10, 3, 4, 4);
			g.drawArc(9, 9, 7, 8, 20, 160);
		}
	}

	static final class MembersIcon extends TileIcon
	{
		@Override void paint(Graphics2D g)
		{
			for (int y = 3; y <= 13; y += 5)
			{
				g.fillOval(1, y - 1, 3, 3);
				g.drawLine(7, y, 15, y);
			}
		}
	}

	static final class DropsIcon extends TileIcon
	{
		@Override void paint(Graphics2D g)
		{
			g.drawRoundRect(2, 6, 12, 8, 2, 2);
			g.drawLine(2, 9, 14, 9);
			g.drawLine(8, 1, 8, 5);
			g.drawLine(6, 3, 8, 5);
			g.drawLine(10, 3, 8, 5);
		}
	}

	static final class NewsIcon extends TileIcon
	{
		@Override void paint(Graphics2D g)
		{
			Path2D horn = new Path2D.Double();
			horn.moveTo(2, 6);
			horn.lineTo(6, 6);
			horn.lineTo(13, 2);
			horn.lineTo(13, 14);
			horn.lineTo(6, 10);
			horn.lineTo(2, 10);
			horn.closePath();
			g.draw(horn);
			g.drawLine(4, 10, 5, 14);
		}
	}

	static final class CogIcon extends HoverIcon
	{
		CogIcon() { super(16); }
		@Override void paint(Graphics2D g, Component c)
		{
			g.drawOval(3, 3, 10, 10);
			g.drawOval(6, 6, 4, 4);
			g.setStroke(new BasicStroke(2.6f, BasicStroke.CAP_BUTT, BasicStroke.JOIN_ROUND));
			for (int i = 0; i < 8; i++)
			{
				double a = Math.PI / 4 * i;
				g.draw(new Line2D.Double(8 + 5 * Math.cos(a), 8 + 5 * Math.sin(a), 8 + 7.5 * Math.cos(a), 8 + 7.5 * Math.sin(a)));
			}
		}
	}

	static final class DiscordIcon extends HoverIcon
	{
		private static final Color BLURPLE = new Color(88, 101, 242);

		DiscordIcon() { super(20); }
		@Override Color hoverColor() { return BLURPLE; }
		@Override void paint(Graphics2D g, Component c)
		{
			Path2D body = new Path2D.Double();
			body.moveTo(5, 3.5);
			body.quadTo(10, 2.5, 15, 3.5);
			body.curveTo(18, 7, 19.5, 11, 19, 15);
			body.quadTo(17, 17, 14.5, 17.5);
			body.lineTo(13.5, 15.5);
			body.quadTo(10, 16.8, 6.5, 15.5);
			body.lineTo(5.5, 17.5);
			body.quadTo(3, 17, 1, 15);
			body.curveTo(0.5, 11, 2, 7, 5, 3.5);
			body.closePath();
			Area face = new Area(body);
			face.subtract(new Area(new Ellipse2D.Double(5.5, 8.5, 3, 3.5)));
			face.subtract(new Area(new Ellipse2D.Double(11.5, 8.5, 3, 3.5)));
			g.fill(face);
		}
	}

	static final class DotIcon implements Icon
	{
		private final Color color;

		DotIcon(Color color) { this.color = color; }
		@Override public int getIconWidth() { return 7; }
		@Override public int getIconHeight() { return 7; }
		@Override public void paintIcon(Component component, Graphics graphics, int x, int y)
		{
			Graphics2D g = (Graphics2D) graphics.create();
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setColor(color);
			g.fillOval(x, y, 7, 7);
			g.dispose();
		}
	}

	static final class CheckIcon implements Icon
	{
		@Override public int getIconWidth() { return 14; }
		@Override public int getIconHeight() { return 14; }
		@Override public void paintIcon(Component component, Graphics graphics, int x, int y)
		{
			Graphics2D g = (Graphics2D) graphics.create();
			g.translate(x, y);
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setColor(SUCCESS);
			g.fillOval(0, 0, 14, 14);
			g.setColor(CARD);
			g.setStroke(new BasicStroke(2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			Path2D tick = new Path2D.Double();
			tick.moveTo(3.5, 7.5);
			tick.lineTo(6, 10);
			tick.lineTo(10.5, 4.5);
			g.draw(tick);
			g.dispose();
		}
	}

	static final class PinnedIcon implements Icon
	{
		@Override public int getIconWidth() { return 12; }
		@Override public int getIconHeight() { return 12; }
		@Override public void paintIcon(Component component, Graphics graphics, int x, int y)
		{
			Graphics2D g = (Graphics2D) graphics.create();
			g.translate(x, y);
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setColor(ACCENT);
			g.fillRect(4, 1, 4, 5);
			g.fillPolygon(new int[] {1, 11, 8, 4}, new int[] {8, 8, 5, 5}, 4);
			g.setStroke(new BasicStroke(1.4f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.drawLine(3, 1, 9, 1);
			g.drawLine(6, 8, 6, 11);
			g.dispose();
		}
	}

	static final class UnreadIcon implements Icon
	{
		@Override public int getIconWidth() { return 8; }
		@Override public int getIconHeight() { return 8; }
