	private void renderHome()
	{
		if (homeBuilt)
		{
			for (Section section : sections) summarize(section);
			return;
		}
		setHeader("TSG Hub", plugin.getDetectedPlayerName(), false, true);
		page.removeAll();
		for (int i = 0; i < sections.size(); i += 2)
		{
			boolean pair = i + 1 < sections.size();
			JPanel row = panel(new GridLayout(1, pair ? 2 : 1, 6, 0));
			row.add(sectionTile(sections.get(i), pair));
			if (pair) row.add(sectionTile(sections.get(i + 1), true));
			page.add(fitHeight(row));
			page.add(Box.createVerticalStrut(LIST_GAP));
		}
		if (update != null)
		{
			page.add(Box.createVerticalStrut(GAP_S));
			JLabel notice = label("Update available. Restart RuneLite.", WARNING, smallFont());
			notice.setHorizontalAlignment(JLabel.CENTER);
			notice.setToolTipText("Version " + update);
			page.add(fitHeight(notice));
		}
		refreshPage();
		homeBuilt = true;
	}

	void setConnection(TsgHubSocket.State state)
	{
		Color color = state == TsgHubSocket.State.CONNECTED ? SUCCESS : state == TsgHubSocket.State.CONNECTING ? WARNING : TsgHubTheme.ERROR;
		String status = state == TsgHubSocket.State.CONNECTED ? "Connected" : state == TsgHubSocket.State.CONNECTING ? "Connecting…" : "Disconnected";
		connection.setIcon(new DotIcon(color));
		connection.setText(status);
