	private void fillMemberMenu()
	{
		memberMenu.removeAll();
		Component invoker = memberMenu.getInvoker();
		while (invoker != null && !(invoker instanceof JComponent && ((JComponent) invoker).getClientProperty(MEMBER_KEY) != null)) invoker = invoker.getParent();
		if (invoker == null) return;
		JsonObject member = (JsonObject) ((JComponent) invoker).getClientProperty(MEMBER_KEY);
		String name = str(member, "displayName");
		javax.swing.JMenuItem lookup = new javax.swing.JMenuItem("Lookup");
		lookup.addActionListener(e -> showLookup(name, TsgHubPresence.accountType(member)));
		memberMenu.add(lookup);
		if (plugin.canManageOrganizerUi() && notesLoaded) addNoteItems(memberMenu, member);
	}

	private void showLookup(String name, int accountType)
	{
		lookupName = name;
		lookupType = accountType;
		if (view != View.LOOKUP) lookupReturn = view;
		setView(View.LOOKUP);
		loadLookup();
	}

	private void loadLookup()
	{
		int seq = ++lookupSeq;
		lookupResult = null;
		lookupError = "";
		renderLookup();
		setBusy(true);
		plugin.lookupHiscores(lookupName, lookupType).whenComplete((result, error) -> SwingUtilities.invokeLater(() -> {
			setBusy(false);
			if (seq != lookupSeq) return;
			lookupResult = result;
			lookupError = error != null ? friendlyError(error) : result == null ? "Not found" : "";
			if (view == View.LOOKUP) renderLookup();
		}));
	}

	private void renderLookup()
	{
		HiscoreResult result = lookupResult;
		setHeader(lookupName, result == null ? TsgHubHiscores.endpoint(lookupType).getName() + " hiscores" : TsgHubHiscores.subtitle(result), true, true);
		page.removeAll();
		if (!lookupError.isEmpty())
		{
			page.add("Not found".equals(lookupError)
				? errorPanel("Not on the hiscores", lookupName + " isn't ranked on the " + TsgHubHiscores.endpoint(lookupType).getName() + " hiscores.")
				: errorPanel("Lookup failed", lookupError));
		}
		else if (result == null)
		{
			page.add(caption("Looking up " + lookupName + "..."));
		}
		else
		{
			page.add(sectionHeading("Skills", null));
			page.add(TsgHubHiscores.skillGrid(result));
			page.add(Box.createVerticalStrut(GAP_XS));
			page.add(TsgHubHiscores.totalRow(result));
			addScores("Bosses", result, HiscoreSkillType.BOSS);
			addScores("Activities", result, HiscoreSkillType.ACTIVITY);
		}
		refreshPage();
	}

	private void addScores(String heading, HiscoreResult result, HiscoreSkillType type)
	{
		List<HiscoreSkill> scored = TsgHubHiscores.scored(result, type);
		if (scored.isEmpty()) return;
		page.add(Box.createVerticalStrut(GAP_L));
		page.add(sectionHeading(heading + " (" + scored.size() + ")", null));
		for (HiscoreSkill skill : scored)
		{
			page.add(TsgHubHiscores.scoreRow(result, skill, plugin.sprites()));
			page.add(Box.createVerticalStrut(2));
		}
	}

	private void addNoteItems(javax.swing.JPopupMenu menu, JsonObject member)
	{
		String name = str(member, "displayName");
		String altOf = str(member, "altOf");
		String note = str(member, "note");
		boolean alt = TsgHubRoster.isAltRank(str(member, "rank"));
		List<JsonObject> active = TsgHubRoster.activeWarnings(array(member, "warnings"));
		menu.addSeparator();
		javax.swing.JMenuItem edit = new javax.swing.JMenuItem(alt ? "Edit alt and admin note" : "Edit admin note");
		edit.addActionListener(e -> promptMemberNote(name, alt, altOf, note));
		menu.add(edit);
		menu.addSeparator();
		javax.swing.JMenuItem warn = new javax.swing.JMenuItem("Add warning...");
		warn.addActionListener(e -> promptWarning(name, active.size()));
		menu.add(warn);
		if (!active.isEmpty())
		{
			javax.swing.JMenuItem revoke = new javax.swing.JMenuItem("Revoke a warning...");
			revoke.addActionListener(e -> promptRevoke(name, active));
			menu.add(revoke);
		}
	}

	private static void inheritMenu(java.awt.Container parent)
	{
		for (Component child : parent.getComponents())
		{
			if (child instanceof JComponent) ((JComponent) child).setInheritsPopupMenu(true);
			if (child instanceof java.awt.Container) inheritMenu((java.awt.Container) child);
		}
	}

	private void promptWarning(String name, int active)
	{
		javax.swing.JTextArea reason = new javax.swing.JTextArea(3, 22);
		reason.setLineWrap(true);
		reason.setWrapStyleWord(true);
		javax.swing.JComboBox<String> expiry = new javax.swing.JComboBox<>(new String[] {"After 30 days", "After 90 days", "Never"});
		expiry.setAlignmentX(Component.LEFT_ALIGNMENT);
		JPanel form = stack();
		form.add(label(active == 0 ? name + " has no active warnings." : name + " has " + active + " active warning" + (active == 1 ? "." : "s."), MUTED, smallFont()));
		form.add(Box.createVerticalStrut(GAP_M));
		form.add(new JLabel("Reason"));
		form.add(new javax.swing.JScrollPane(reason));
		form.add(Box.createVerticalStrut(GAP_M));
		form.add(new JLabel("Expires"));
		form.add(expiry);
		form.add(Box.createVerticalStrut(GAP_M));
		form.add(label("Only admins see warnings.", MUTED, smallFont()));
		Object[] options = {"Add warning", "Cancel"};
		if (JOptionPane.showOptionDialog(this, form, "Warn " + name, JOptionPane.DEFAULT_OPTION, JOptionPane.PLAIN_MESSAGE, null, options, options[0]) != 0) return;
		String text = reason.getText().trim();
		if (text.isEmpty())
		{
			setStatus("Add a reason for the warning.", Tone.ERROR);
			return;
		}
		if (text.length() > MAX_WARNING_LENGTH)
		{
			setStatus("Keep the reason to " + MAX_WARNING_LENGTH + " characters.", Tone.ERROR);
			return;
		}
		plugin.presence().addWarning(name, text, EXPIRY_DAYS[expiry.getSelectedIndex()]);
	}

	private void promptRevoke(String name, List<JsonObject> active)
	{
		Instant now = clock.instant();
		ZoneId zone = ZoneId.systemDefault();
		javax.swing.ButtonGroup group = new javax.swing.ButtonGroup();
		List<javax.swing.JRadioButton> choices = new ArrayList<>();
		JPanel form = stack();
		for (JsonObject warning : active)
		{
			String meta = TsgHubFormat.shortDate(str(warning, "issuedAt"), now, zone) + " · " + escape(str(warning, "issuedBy"));
			javax.swing.JRadioButton choice = plain(new javax.swing.JRadioButton(html(escape(str(warning, "reason")) + "<br>" + tipLine(MUTED, meta), 220)), TEXT);
			choice.setSelected(choices.isEmpty());
			group.add(choice);
			choices.add(choice);
			form.add(choice);
			form.add(Box.createVerticalStrut(GAP_S));
		}
		JTextField reason = new JTextField(22);
		form.add(Box.createVerticalStrut(GAP_S));
		form.add(new JLabel("Reason for revoking (optional)"));
		form.add(reason);
		Object[] options = {"Revoke", "Cancel"};
		if (JOptionPane.showOptionDialog(this, form, "Revoke a warning for " + name, JOptionPane.DEFAULT_OPTION, JOptionPane.PLAIN_MESSAGE, null, options, options[0]) != 0) return;
		for (int i = 0; i < choices.size(); i++)
		{
			if (choices.get(i).isSelected()) plugin.presence().revokeWarning(name, str(active.get(i), "id"), reason.getText().trim());
		}
	}

	private void promptMemberNote(String name, boolean alt, String altOf, String note)
	{
		List<String> candidates = mainCandidates(name);
		TsgHubMemberPicker main = new TsgHubMemberPicker(candidates, altOf);
		javax.swing.JTextArea notes = new javax.swing.JTextArea(note, 4, 20);
		notes.setLineWrap(true);
		notes.setWrapStyleWord(true);
		JPanel form = stack();
		if (alt)
		{
			form.add(new JLabel("Alt of (main character)"));
			form.add(main);
			form.add(Box.createVerticalStrut(GAP_M));
		}
		form.add(new JLabel("Admin note (only admins see this)"));
		form.add(new javax.swing.JScrollPane(notes));
		if (JOptionPane.showConfirmDialog(this, form, name, JOptionPane.OK_CANCEL_OPTION, JOptionPane.PLAIN_MESSAGE) != JOptionPane.OK_OPTION) return;
		String typed = main.getText();
		String nextMain = typed.equals(altOf) ? altOf : PlayerNames.resolveName(candidates, typed);
		String nextNote = notes.getText().trim();
		if (samePlayer(nextMain, name))
		{
			setStatus("A character can't be its own alt.", Tone.ERROR);
			return;
		}
		if (nextNote.length() > 500)
		{
			setStatus("Keep the note to 500 characters.", Tone.ERROR);
			return;
		}
		if (nextMain.equals(altOf) && nextNote.equals(note)) return;
		plugin.presence().saveNote(name, nextMain, nextNote);
	}

	private List<String> mainCandidates(String alt)
	{
		List<String> names = new ArrayList<>();
		for (JsonArray list : new JsonArray[] {members, offlineMembers})
		{
			if (list == null) continue;
			for (int i = 0; i < list.size(); i++)
			{
				JsonObject member = list.get(i).getAsJsonObject();
				String candidate = str(member, "displayName");
				if (!samePlayer(candidate, alt) && !TsgHubRoster.isAltRank(str(member, "rank"))) names.add(candidate);
			}
		}
		names.sort(String.CASE_INSENSITIVE_ORDER);
		return names;
	}

	void setDrops(JsonArray drops)
	{
		if (Objects.equals(this.drops, drops)) return;
		this.drops = drops;
		if (shows(View.DROPS)) renderDrops();
	}

	private JPanel buildDropsView()
	{
		JPanel filters = panel(new java.awt.GridLayout(1, 2, GAP_S, 0));
		dropTypeIndex = sessionIndex(DROP_TYPE, dropType.getItemCount());
		dropValueIndex = sessionIndex(DROP_VALUE, dropValue.getItemCount());
		dropType.setSelectedIndex(dropTypeIndex);
		dropValue.setSelectedIndex(dropValueIndex);
		dropType.setToolTipText("Drop type");
		dropValue.setToolTipText("Minimum value");
		dropType.addActionListener(e -> changeDropFilter());
		dropValue.addActionListener(e -> changeDropFilter());
		filters.add(dropType);
		filters.add(dropValue);
		dropsView.setOpaque(false);
		dropsView.add(filters, BorderLayout.NORTH);
		dropsView.add(dropsScroll, BorderLayout.CENTER);
		return dropsView;
	}

	private int sessionIndex(String key, int size)
	{
		try
		{
			int index = Integer.parseInt(plugin.session().get(key));
			return index >= 0 && index < size ? index : 0;
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}

	private void changeDropFilter()
	{
		if (dropTypeIndex == dropType.getSelectedIndex() && dropValueIndex == dropValue.getSelectedIndex()) return;
		dropTypeIndex = Math.max(0, dropType.getSelectedIndex());
		dropValueIndex = Math.max(0, dropValue.getSelectedIndex());
		plugin.session().set(DROP_TYPE, dropTypeIndex == 0 ? "" : String.valueOf(dropTypeIndex));
		plugin.session().set(DROP_VALUE, dropValueIndex == 0 ? "" : String.valueOf(dropValueIndex));
		if (shows(View.DROPS)) renderDrops();
		plugin.drops().load(false);
	}

	String dropsQuery()
	{
		String query = "";
		String kind = DROP_KINDS[dropTypeIndex];
		if (!kind.isEmpty()) query += "&kind=" + kind;
		if (dropTypeIndex == 1) query += "&player=" + TsgHubApi.encode(plugin.getDetectedPlayerName());
		if (dropValueIndex > 0) query += "&minValue=" + DROP_VALUES[dropValueIndex];
		return query;
	}

	void showDrops()
	{
		if (pinned == View.DROPS)
		{
			dock.expand();
			plugin.drops().load(false);
			return;
		}
		setView(View.DROPS);
		renderDrops();
		plugin.drops().load(false);
	}

	private void renderDrops()
	{
		viewHeader(View.DROPS, "Drops", "", "");
		dropsPage.removeAll();
		if (drops == null)
		{
			dropsPage.add(caption("Loading drops..."));
		}
		else if (drops.size() == 0 && dropTypeIndex == 0 && dropValueIndex == 0)
		{
			dropsPage.add(errorPanel("No drops yet", "Clan broadcasts for drops, raid loot, pets and collection log items show up here."));
		}
		else
		{
			Instant now = clock.instant();
			ZoneId zone = ZoneId.systemDefault();
			String self = plugin.getDetectedPlayerName();
			JsonArray shown = new JsonArray();
			for (int i = 0; i < drops.size(); i++)
			{
				JsonObject drop = drops.get(i).getAsJsonObject();
				if (TsgHubDrops.dropMatches(drop, dropTypeIndex, DROP_VALUES[dropValueIndex], self)) shown.add(drop);
			}
			if (shown.size() == 0) dropsPage.add(errorPanel("No matching drops", "Nothing recent matches this type and value."));
			String day = null;
			for (int i = 0; i < shown.size(); i++)
			{
				JsonObject drop = shown.get(i).getAsJsonObject();
				String nextDay = TsgHubDrops.dropDay(str(drop, "receivedAt"), now, zone);
				if (!nextDay.equals(day))
				{
					dropsPage.add(listHeading(nextDay, i == 0));
					day = nextDay;
				}
				dropsPage.add(dropCard(drop, now, zone));
				dropsPage.add(Box.createVerticalStrut(LIST_GAP));
			}
		}
		refresh(dropsPage);
	}

	private JPanel dropCard(JsonObject drop, Instant now, ZoneId zone)
	{
		String player = str(drop, "player");
		boolean self = samePlayer(player, plugin.getDetectedPlayerName());
		JPanel card = card();
		if (self) highlightSelf(card);
		JLabel icon = dropIcon(integer(drop, "itemId", 0));
		if (icon != null) card.add(icon, BorderLayout.WEST);

		JLabel name = shrinkable(boldLabel(TsgHubDrops.dropItem(drop)));
		JPanel extras = panel(new FlowLayout(FlowLayout.RIGHT, 3, 0));
		for (String tag : TsgHubDrops.dropTags(drop)) extras.add(badge(tag, TAG_COLORS.getOrDefault(tag, TAG_DEFAULT)));
		long value = drop.has("value") ? drop.get("value").getAsLong() : 0;
		if (value > 0) extras.add(label(formatGp(value), coinColor(value), smallFont()));
		card.add(fillWidth(twoLines(
			row(name, caption(TsgHubDrops.dropWhen(str(drop, "receivedAt"), now, zone))),
			row(shrinkable(label(player, ACCENT, smallFont())), extras))), BorderLayout.CENTER);
		fullTextTooltip(card, () -> TsgHubDrops.dropTooltip(drop));
		return fitHeight(card);
	}

	private static JPanel fillWidth(Component content)
	{
		JPanel slot = panel(new GridBagLayout());
		GridBagConstraints fill = new GridBagConstraints();
		fill.weightx = 1;
		fill.fill = GridBagConstraints.HORIZONTAL;
		slot.add(content, fill);
		return slot;
	}

	private JLabel dropIcon(int itemId)
	{
		if (itemId <= 0) return null;
		AsyncBufferedImage image = plugin.getItemImage(itemId);
		if (image == null) return null;
		JLabel label = new JLabel();
		label.setVerticalAlignment(JLabel.CENTER);
		label.setPreferredSize(new Dimension(DROP_ICON_W, 32));
		image.addTo(label);
		return label;
	}

