	private void renderCurrentGroup(JsonObject group)
	{
		setPartyHeader(group);

		groupsPage.add(groupMembers);
		groupsPage.add(Box.createVerticalStrut(GAP_L));

		JButton title = button("Set title");
		title.setToolTipText("Name the party. Leave blank to title it by location.");
		title.setEnabled(group != null);
		title.addActionListener(e -> promptTitle(group));
		if (plugin.groups().isLeader())
		{
			boolean locked = bool(group, "locked");
			JButton lock = button(locked ? "Unlock party" : "Lock party");
			lock.setToolTipText(locked ? "Let clanmates join again" : "Stop anyone else from joining");
			lock.addActionListener(e -> {
				lock.setEnabled(false);
				plugin.groups().setLocked(!locked);
			});
			JPanel leaderActions = panel(new GridLayout(1, 2, 4, 0));
			leaderActions.add(title);
			leaderActions.add(lock);
			groupsPage.add(fitHeight(leaderActions));
		}
		else groupsPage.add(fitHeight(title));
		groupsPage.add(Box.createVerticalStrut(GAP_S));

		String currentId = group == null ? "" : str(group, "id");
		int others = 0;
		if (groupList != null)
			for (int i = 0; i < groupList.size(); i++)
				if (!str(groupList.get(i).getAsJsonObject(), "id").equals(currentId)) others++;
		JPanel actions = panel(new GridLayout(1, 2, 4, 0));
		JButton browse = button(others == 0 ? "Other parties" : "Other parties (" + others + ")");
		browse.setToolTipText("See the clan's other parties and switch to one");
		browse.addActionListener(e -> {
			browsingParties = true;
			groupError.setVisible(false);
			renderGroups();
		});
		JButton leave = dangerButton("Leave party");
		leave.addActionListener(e -> {
			leave.setEnabled(false);
			plugin.groups().leave();
		});
		actions.add(browse);
		actions.add(leave);
		groupsPage.add(fitHeight(actions));
		groupsPage.add(groupError);
	}

	private void renderGroupList(JsonObject current)
	{
		viewHeader(View.GROUPS, current != null ? "Other parties" : "Parties", "", partiesSummary());
		if (pinned != View.GROUPS) back.setToolTipText(current != null ? "Back to your party" : "Home");
		if (groupList == null)
		{
			groupsPage.add(caption("Loading parties..."));
		}
		else if (groupList.size() == 0)
		{
			groupsPage.add(errorPanel("No parties yet", "Start one below. Clanmates can join it with one click, no code needed."));
		}
		else
		{
			String currentId = current == null ? "" : str(current, "id");
			List<JsonObject> sorted = objects(groupList);
			sorted.sort(Comparator.comparing((JsonObject g) -> !str(g, "id").equals(currentId)));
			for (JsonObject group : sorted)
			{
				groupsPage.add(groupCard(group, current));
				groupsPage.add(Box.createVerticalStrut(LIST_GAP));
			}
		}

		groupsPage.add(Box.createVerticalStrut(GAP_L));
		createGroupButton.setEnabled(!groupBusy);
		createGroupButton.setText(groupBusy ? "Working..." : "New party");
		groupsPage.add(fitHeight(createGroupButton));
		groupsPage.add(groupError);
		groupsPage.add(Box.createVerticalStrut(GAP_M));
		groupsPage.add(hint(current != null ? "Joining or starting another party leaves your current one."
			: "Party members see each other's health, prayer, gear, inventory and skills while they're in the party."));
		if (plugin.groups().inOtherParty())
		{
			groupsPage.add(Box.createVerticalStrut(GAP_S));
			groupsPage.add(wrapped("You're in a RuneLite party from outside TSG Hub. Joining or starting a party here leaves it.", WARNING, smallFont(), TEXT_W));
		}
	}

	private JPanel groupCard(JsonObject group, JsonObject current)
	{
		JsonArray members = array(group, "members");
		String leader = str(group, "leaderName");
		int world = 0;
		boolean leaderListed = false;
		String self = plugin.getDetectedPlayerName();
		List<String> names = new ArrayList<>();
		for (JsonObject member : objects(members))
		{
			String name = str(member, "displayName");
			if (samePlayer(name, leader))
			{
				world = integer(member, "world", 0);
				leaderListed = true;
				names.add(0, samePlayer(name, self) ? selfName(escape(name)) : "<font color='" + toHexColor(TEXT) + "'>" + escape(name) + "</font>");
			}
			else names.add(nameHtml(name, self));
		}
		JPanel card = card();
		boolean mine = current != null && str(group, "id").equals(str(current, "id"));
		if (mine) highlightSelf(card);
		boolean locked = !mine && bool(group, "locked");
		String title = mine ? currentTitle(group) : TsgHubGroups.partyTitle(group);

		JLabel heading = shrinkable(label(title, locked ? MUTED : TEXT, boldFont()));
		heading.putClientProperty("html.disable", Boolean.TRUE);
		if (bool(group, "locked"))
		{
			heading.setIcon(new LockIcon());
			heading.setIconTextGap(5);
		}
		int myWorld = myPartyWorld();
		boolean sameWorld = !mine && world > 0 && world == myWorld;
		JPanel top = world > 0 ? row(heading, label("W" + world, sameWorld ? SUCCESS : MUTED, smallFont())) : row(heading, new JLabel());

		Map.Entry<String, Integer> area = TsgHubGroups.areaSummary(members);
		boolean showArea = area != null && !area.getKey().equalsIgnoreCase(title) && (area.getValue() >= 2 || members.size() == 1);
		String extra = showArea ? area.getKey() : leaderListed || leader.isEmpty() ? "" : "Led by " + leader;
		JLabel detail = shrinkable(showArea ? label(extra, SUCCESS, smallFont()) : caption(extra));
		detail.putClientProperty("html.disable", Boolean.TRUE);
		JLabel who = label(html(String.join(", ", names), CARD_TEXT_W), MUTED, smallFont());
		JPanel text = extra.isEmpty() ? twoLines(top, who) : twoLines(top, detail);
		if (!extra.isEmpty())
		{
			text.add(Box.createVerticalStrut(GAP_XS));
			text.add(who);
		}
		card.add(text, BorderLayout.CENTER);

		fullTextTooltip(card, null);
		if (locked) return fitHeight(card);
		clickable(card, () -> {
			if (mine)
			{
				browsingParties = false;
				renderGroups();
				return;
			}
			if (groupBusy) return;
			if (current != null && !confirm(this, "Switch parties", "Leave " + currentTitle(current) + " and join " + title + "?", "Switch", false)) return;
			groupBusy = true;
			groupError.setVisible(false);
			renderGroups();
			plugin.groups().join(str(group, "id"));
		});
		return fitHeight(card);
	}

	private int myPartyWorld()
	{
		if (groupList == null) return 0;
		for (JsonObject group : objects(groupList))
			for (JsonObject member : objects(array(group, "members")))
				if (samePlayer(str(member, "displayName"), plugin.getDetectedPlayerName())) return integer(member, "world", 0);
		return 0;
	}

	private String currentTitle(JsonObject group)
	{
		if (!str(group, "activity").isEmpty()) return TsgHubGroups.partyTitle(group);
		Map.Entry<String, Integer> live = TsgHubGroups.areaSummary(plugin.groups().liveAreas());
		return live != null ? live.getKey() : TsgHubGroups.partyTitle(group);
	}

	private void promptTitle(JsonObject group)
	{
		Object input = JOptionPane.showInputDialog(this, "Party title (leave blank to title it by location)", "Set title",
			JOptionPane.PLAIN_MESSAGE, null, null, str(group, "activity"));
		if (input == null) return;
		String title = input.toString().trim();
		if (title.length() > 40)
		{
			groupActionFailed("Keep the title to 40 characters.");
			return;
		}
		groupError.setVisible(false);
		plugin.groups().setTitle(title);
	}

	private void submitCreateGroup()
	{
		if (groupBusy) return;
		JsonObject current = plugin.groups().inGroup() ? plugin.groups().currentGroup() : null;
		if (current != null && !confirm(this, "Start a new party", "Leave " + currentTitle(current) + " and start a new party?", "Start", false)) return;
		groupBusy = true;
		groupError.setVisible(false);
		renderGroups();
		plugin.groups().create();
	}

	private void setView(View next)
	{
		view = next;
		homeBuilt = false;
		boardShowing = next == View.BOARD;
		boolean docked = pinned != null && !gated(next);
		membersWanted = next == View.MEMBERS || next == View.HOME || docked && pinned == View.MEMBERS;
		groupsWanted = next == View.GROUPS || next == View.HOME || docked && pinned == View.GROUPS;
		dropsWanted = next == View.DROPS || docked && pinned == View.DROPS;
		if (next != View.COMPETITION) openCompetitionId = null;
		centerLayout.show(center, cardName(next));
		discord.setVisible(next == View.HOME);
		dock.setShown(!gated(next));
		pin.setVisible(pinnable(next));
		title.setText(html(escape(titleText), titleWidth()));
		back.setToolTipText(next == View.LOOKUP ? backLabel(lookupReturn) : next == View.EVENTS || next == View.GROUPS || next == View.MEMBERS || next == View.DROPS || next == View.NEWS ? "Home" : "Back to events");
	}

	private static String cardName(View next)
	{
		switch (next)
		{
			case BOARD: return "board";
			case GROUPS: return "groups";
			case MEMBERS: return "members";
			case DROPS: return "drops";
			default: return "page";
		}
	}

	private static boolean gated(View next)
	{
		return next == View.LOGGED_OUT || next == View.NOT_IN_CLAN || next == View.SHARING_OFF;
	}

	private static boolean pinnable(View next)
	{
		return next == View.MEMBERS || next == View.DROPS || next == View.GROUPS;
	}

	private boolean shows(View owner)
	{
		return view == owner || pinned == owner;
	}

	private static String backLabel(View target)
	{
		switch (target)
		{
			case MEMBERS: return "Members";
			case BOARD:
			case COMPETITION: return "Back to event";
			case EVENTS: return "Events";
			case DROPS: return "Drops";
			case GROUPS: return "Parties";
			default: return "Home";
		}
	}

	private void reopen(View target)
	{
		switch (target)
		{
			case MEMBERS: showMembers(); break;
			case DROPS: showDrops(); break;
			case GROUPS: showParties(); break;
			case EVENTS: showEventList(); break;
			case BOARD:
				if (boardEvent != null) showBoard(boardEvent, boardDisplayName, true);
				else showHome();
				break;
			case COMPETITION:
				if (competitionEvent != null) showCompetition(competitionEvent, competitionName, true);
				else showHome();
				break;
			default: showHome();
		}
	}

	private void viewHeader(View owner, String titleText, String subtitleText, String dockDetail)
	{
		if (pinned == owner) dock.setTitle(titleText, dockDetail);
		else setHeader(titleText, subtitleText, true, true);
	}

	private JComponent pane(View owner)
	{
		return owner == View.MEMBERS ? membersScroll : owner == View.DROPS ? dropsView : groupsScroll;
	}

	private Icon pinIcon(View owner)
	{
		return owner == View.MEMBERS ? new MembersIcon() : owner == View.DROPS ? new DropsIcon() : new PartyIcon();
	}

	void pinCurrent()
	{
		if (!pinnable(view)) return;
		View next = view;
		if (pinned != null) unpin();
		pin(next);
		showHome();
	}

	private void pin(View next)
	{
		pinned = next;
		plugin.session().set(DOCK_VIEW, next.name());
		dock.pin(pinIcon(next), pane(next));
		dock.expand();
		renderPinned();
	}

	private void unpin()
	{
		if (pinned == null) return;
		View was = pinned;
		pinned = null;
		plugin.session().set(DOCK_VIEW, "");
		dock.unpin();
		center.add(pane(was), cardName(was));
		setView(view);
	}

	private void restorePin()
	{
		String saved = plugin.session().get(DOCK_VIEW);
		for (View candidate : View.values())
			if (pinnable(candidate) && candidate.name().equals(saved))
			{
				pinned = candidate;
				dock.pin(pinIcon(candidate), pane(candidate));
				setView(view);
				renderPinned();
			}
	}

	private void renderPinned()
	{
		if (pinned == View.MEMBERS) renderMembers();
		else if (pinned == View.DROPS) renderDrops();
		else if (pinned == View.GROUPS) renderGroups();
	}

