	private String ownTeamId()
	{
		return teamIdFor(boardEvent, boardDisplayName);
	}

	private void renderSummary()
	{
		boardSummary.removeAll();
		String teamId = ownTeamId();
		List<JsonObject> ranked = rankedTeams(boardEvent);
		JsonObject score = scoreFor(array(boardEvent, "teamScores"), teamId);
		int totalTasks = array(boardEvent, "tasks").size();
		int completed = integer(score, "completedTasks", 0);
		String teamName = "No team";
		int rank = 0;
		for (int i = 0; i < ranked.size(); i++)
		{
			if (str(ranked.get(i), "id").equals(teamId))
			{
				teamName = str(ranked.get(i), "name");
				rank = i + 1;
			}
		}

		JPanel card = card();
		JPanel row = row();
		row.add(label(html(escape(teamName), CARD_TITLE_W), TEXT, boldFont()), BorderLayout.CENTER);
		if (rank > 0 && !bool(boardEvent, "hideScores"))
		{
			JLabel rankLabel = label("#" + rank + " of " + ranked.size(), rank == 1 ? ACCENT : MUTED, boldFont());
			row.add(rankLabel, BorderLayout.EAST);
		}
		card.add(row, BorderLayout.NORTH);
		ProgressBar bar = progressBar(completed, Math.max(totalTasks, 1));
		bar.setLeftLabel(integer(score, "points", 0) + " pts");
		bar.setRightLabel(completed + "/" + totalTasks + " tasks");
		card.add(bar, BorderLayout.CENTER);
		JPanel prizes = prizeRow(boardEvent, smallFont());
		if (prizes != null)
		{
			prizes.setBorder(BorderFactory.createEmptyBorder(5, 0, 0, 0));
			card.add(prizes, BorderLayout.SOUTH);
		}
		boardSummary.add(fitHeight(card));
		refresh(boardSummary);
	}

	private void renderTasks()
	{
		if (boardEvent == null) return;
		tasksTab.removeAll();
		JsonArray tasks = array(boardEvent, "tasks");
		JsonObject score = scoreFor(array(boardEvent, "teamScores"), ownTeamId());
		JsonArray progressRows = array(score, "tasks");

		List<JsonObject> open = new ArrayList<>();
		List<JsonObject> done = new ArrayList<>();
		for (JsonObject task : objects(tasks))
		{
			boolean completed = bool(progressFor(progressRows, str(task, "id")), "completed");
			(completed ? done : open).add(task);
		}

		JPanel controls = panel(new BorderLayout());
		controls.add(hideCompleted, BorderLayout.WEST);
		JLabel left = caption(open.size() + " left");
		left.setBorder(BorderFactory.createEmptyBorder(0, 0, 0, 4));
		controls.add(left, BorderLayout.EAST);
		tasksTab.add(fitHeight(controls));
		tasksTab.add(Box.createVerticalStrut(GAP_S));

		if (tasks.size() == 0)
		{
			tasksTab.add(errorPanel("No tasks yet", "The admins haven't added tasks to this event yet."));
		}
		else if (open.isEmpty() && hideCompleted.isSelected())
		{
			tasksTab.add(errorPanel("All done!", "Your team has completed every task."));
		}
		for (JsonObject task : open) addTaskCard(task, progressFor(progressRows, str(task, "id")));
		if (!hideCompleted.isSelected())
		{
			for (JsonObject task : done) addTaskCard(task, progressFor(progressRows, str(task, "id")));
		}
		refresh(tasksTab);
	}

	private void addTaskCard(JsonObject task, JsonObject progress)
	{
		tasksTab.add(taskCard(task, progress));
		tasksTab.add(Box.createVerticalStrut(LIST_GAP));
	}

	private JPanel taskCard(JsonObject task, JsonObject progress)
	{
		String taskId = str(task, "id");
		boolean completed = bool(progress, "completed");
		boolean individual = "individual".equals(str(task, "scope"));
		boolean solo = "solo".equals(str(task, "scope"));

		JPanel card = card();
		JLabel name = shrinkable(label(str(task, "title"), completed ? MUTED : TEXT, boldFont()));
		name.putClientProperty("html.disable", Boolean.TRUE);
		if (completed) name.setIcon(new CheckIcon());
		JLabel points = label(integer(task, "points", 1) + " pts", completed ? MUTED : ACCENT, smallFont());
		card.add(row(name, north(points)), BorderLayout.NORTH);

		JPanel body = stack();
		String description = str(task, "description").trim();
		if (!description.isEmpty() && !completed) body.add(cardNote(description));

		int value = integer(progress, "progress", 0);
		int target = Math.max(1, integer(progress, "target", 1));
		JsonObject mine = individual || solo ? myEntry(progress) : null;
		if (completed)
		{
			boolean creditedToOrganizer = creditedToOrganizer(progress);
			String line = creditedToOrganizer ? "Marked complete by an admin" : completedLine(progress);
			if (!"Completed".equals(line)) body.add(label(line, SUCCESS, smallFont()));
		}
		else if (addSetProgress(body, individual || solo ? mine : progress, individual || solo))
		{
			if (individual) body.add(teammatesLine(mine, value, target));
			if (solo) addSoloLeader(body, progress);
		}
		else if (solo)
		{
			int have = mine == null ? 0 : integer(mine, "progress", 0);
			if (target > 1) addBar(body, have, target, "You: " + have + "/" + target);
			addSoloLeader(body, progress);
		}
		else if (individual)
		{
			int have = mine == null ? 0 : integer(mine, "progress", 0);
			int need = mine == null ? 1 : integer(mine, "target", 1);
			if (mine != null && need > 1 && !bool(mine, "completed")) addBar(body, have, need, "You: " + have + "/" + need);
			body.add(teammatesLine(mine, value, target));
		}
		else if (target > 1) addBar(body, value, target, value + " / " + target);
		boolean setTile = array(progress, "alternatives").size() > 0 || progress.has("items");
		if (!individual && !solo && (!setTile || completed))
		{
			String amounts = contributorsHtml(progress, " · ", CARD_CONTRIBUTORS, boardDisplayName);
			if (!amounts.isEmpty()) body.add(cardNoteHtml(amounts));
		}
		addLineSpacing(body);
		addScopeIcon(body, solo, individual);
		card.add(body, BorderLayout.CENTER);
		lazyTooltip(card, () -> taskTooltip(task, progress, truncated(name)));
		return fitHeight(card);
	}

	private static void addScopeIcon(JPanel body, boolean solo, boolean individual)
	{
		JLabel scope = new JLabel(new ScopeIcon(solo ? 1 : individual ? 3 : 2));
		scope.setToolTipText(solo ? "Solo: one player completes it" : individual ? "Everyone: each teammate completes it" : "Team: progress is shared");
		JPanel corner = panel(new BorderLayout());
		corner.add(scope, BorderLayout.SOUTH);
		int last = body.getComponentCount() - 1;
		Component line = last >= 0 && body.getComponent(last) instanceof JLabel ? body.getComponent(last) : new JLabel();
		if (line.getParent() == body) body.remove(last);
		body.add(fitHeight(row(line, corner)));
	}

	private JLabel teammatesLine(JsonObject mine, int value, int target)
	{
		String count = value + " of " + target + " teammates done";
		if (mine == null || !bool(mine, "completed")) return caption(count);
		return label(html("<font color='" + toHexColor(SUCCESS) + "'>You're done</font> · " + count, CARD_TEXT_W), MUTED, smallFont());
	}

	private boolean addSetProgress(JPanel body, JsonObject source, boolean mine)
	{
		if (source == null || array(source, "alternatives").size() == 0 && !source.has("items")) return false;
		if (bool(source, "completed")) return true;
		List<SetLine> sets = setLines(source, !mine);
		List<SetLine> shown = new ArrayList<>();
		for (SetLine set : sets) if (set.have > 0) shown.add(set);
		if (shown.isEmpty() && !sets.isEmpty()) shown.add(sets.get(0));
		for (SetLine set : shown)
		{
			ProgressBar bar = progressBar(set.have, set.target);
			bar.setCenterLabel((mine ? "You: " : "") + set.name + " " + set.have + "/" + set.target);
			body.add(Box.createVerticalStrut(GAP_S));
			body.add(bar);
			body.add(Box.createVerticalStrut(GAP_XS));
			if (!set.needed.isEmpty()) body.add(cardNote("Need: " + String.join(", ", set.needed)));
		}
		int notStarted = sets.size() - shown.size();
		if (notStarted > 0) body.add(caption("+" + notStarted + (notStarted == 1 ? " more set" : " more sets") + " not started"));
		return true;
	}

	private static void addLineSpacing(JPanel body)
	{
		Component[] parts = body.getComponents();
		body.removeAll();
		int first = 0;
		while (first < parts.length && parts[first] instanceof Box.Filler) first++;
		for (int i = first; i < parts.length; i++)
		{
			body.add(parts[i]);
			boolean next = i + 1 < parts.length;
			if (next && parts[i] instanceof JLabel && parts[i + 1] instanceof JLabel) body.add(Box.createVerticalStrut(GAP_XS));
		}
	}

	private String taskTooltip(JsonObject task, JsonObject progress, boolean titleCut)
	{
		boolean completed = bool(progress, "completed");
		boolean individual = "individual".equals(str(task, "scope"));
		boolean solo = "solo".equals(str(task, "scope"));
		String head = titleCut ? "<b>" + escape(str(task, "title")) + "</b>" : "";
		String description = str(task, "description").trim();
		if (completed && !description.isEmpty()) head += (head.isEmpty() ? "" : "<br>") + escape(description).replace("\n", "<br>");

		String sections = "";
		if (!completed && !individual && !solo) sections += setSections(progress, head.isEmpty());
		if (individual || solo) sections += memberSections(progress, solo, head.isEmpty());
		else if (sections.isEmpty() && array(progress, "contributors").size() > CARD_CONTRIBUTORS)
		{
			sections += tipSection(head.isEmpty(), tipLine(MUTED, "<b>CONTRIBUTORS</b>")) + tipCard(CARD_HOVER, contributorsHtml(progress, "<br>", 50, boardDisplayName));
		}
		if (head.isEmpty() && sections.isEmpty()) return null;
		return html("<div style='padding:2px'>" + head + sections + "</div>", 240);
	}

	private String setSections(JsonObject progress, boolean first)
	{
		if (array(progress, "alternatives").size() == 0 && !progress.has("items")) return "";
		StringBuilder out = new StringBuilder();
		for (SetLine set : setLines(progress, true))
		{
			if (set.have == 0) continue;
			if (set.found.isEmpty()) continue;
			out.append(tipCard(ACCENT, "<b>" + escape(set.name) + "</b><br>" + set.foundHtml(boardDisplayName)));
		}
		return out.length() == 0 ? "" : tipSection(first, tipLine(MUTED, "<b>FOUND</b>")) + out;
	}

	private String memberSections(JsonObject progress, boolean solo, boolean first)
	{
		List<JsonObject> members = objects(array(progress, "members"));
		if (members.isEmpty()) return "";
		members.sort((a, b) -> integer(b, "progress", 0) - integer(a, "progress", 0));
		List<String> done = new ArrayList<>();
		List<String> waiting = new ArrayList<>();
		for (JsonObject member : members)
		{
			String name = nameHtml(str(member, "displayName"), boardDisplayName);
			int have = integer(member, "progress", 0);
			int need = integer(member, "target", 1);
			if (solo) waiting.add(name + " " + tipLine(MUTED, have + "/" + need));
			else if (bool(member, "completed")) done.add(name);
			else waiting.add(need > 1 ? name + " " + tipLine(MUTED, have + "/" + need) : name);
		}
		if (solo) return tipSection(first, tipLine(MUTED, "<b>STANDINGS</b>")) + tipCard(CARD_HOVER, String.join("<br>", waiting));
		String out = "";
		if (!done.isEmpty()) out += tipSection(first, tipLine(SUCCESS, "<b>DONE</b> ") + tipLine(MUTED, String.valueOf(done.size()))) + tipCard(SUCCESS, String.join("<br>", done));
		if (!waiting.isEmpty()) out += tipSection(first && done.isEmpty(), tipLine(MUTED, "<b>STILL NEED</b> " + waiting.size())) + tipCard(CARD_HOVER, String.join("<br>", waiting));
		return out;
	}

	private void addSoloLeader(JPanel body, JsonObject progress)
	{
		String leader = str(progress, "leader");
		if (leader.isEmpty() || samePlayer(leader, boardDisplayName)) return;
		body.add(caption("Leader: " + leader + " (" + integer(progress, "progress", 0) + "/" + integer(progress, "target", 1) + ")"));
	}

	private JsonObject myEntry(JsonObject progress)
	{
		for (JsonObject member : objects(array(progress, "members")))
			if (samePlayer(str(member, "displayName"), boardDisplayName)) return member;
		return null;
	}

	private void renderScoreboard()
	{
		scoreboardTab.removeAll();
		if (bool(boardEvent, "hideScores"))
		{
			renderHiddenScoreboard();
			return;
		}
		List<JsonObject> ranked = rankedTeams(boardEvent);
		JsonArray scores = array(boardEvent, "teamScores");
		int totalTasks = array(boardEvent, "tasks").size();
		String ownTeam = ownTeamId();
		if (ranked.isEmpty()) scoreboardTab.add(errorPanel("No teams yet", "Teams appear here once an admin adds them."));
		for (int i = 0; i < ranked.size(); i++)
		{
			JsonObject team = ranked.get(i);
			JsonObject score = scoreFor(scores, str(team, "id"));
			boolean mine = str(team, "id").equals(ownTeam);
			JPanel card = card();
			card.setLayout(new BorderLayout(8, 0));
			if (mine) highlightSelf(card);
			card.add(rankLabel(i + 1, boldFont(), 14), BorderLayout.WEST);
			JPanel text = stack();
			text.add(wrapped(str(team, "name"), TEXT, boldFont(), 120));
			text.add(caption(integer(score, "completedTasks", 0) + "/" + totalTasks + " tasks"));
			card.add(text, BorderLayout.CENTER);
			card.add(label(integer(score, "points", 0) + " pts", i == 0 ? ACCENT : TEXT, boldFont()), BorderLayout.EAST);
			scoreboardTab.add(fitHeight(card));
			scoreboardTab.add(Box.createVerticalStrut(LIST_GAP));
		}
		refresh(scoreboardTab);
	}

	private void renderHiddenScoreboard()
	{
		scoreboardTab.add(errorPanel("Scores are hidden", "The admins are keeping scores secret for now. Your own team's progress is on the Tasks tab."));
		List<JsonObject> teams = objects(array(boardEvent, "teams"));
		teams.sort((a, b) -> str(a, "name").compareToIgnoreCase(str(b, "name")));
		String ownTeam = ownTeamId();
		for (JsonObject team : teams)
		{
			boolean mine = str(team, "id").equals(ownTeam);
			JPanel card = card();
			if (mine) highlightSelf(card);
			card.add(wrapped(str(team, "name"), TEXT, plainFont(), CARD_TEXT_W), BorderLayout.CENTER);
			scoreboardTab.add(fitHeight(card));
			scoreboardTab.add(Box.createVerticalStrut(LIST_GAP));
		}
		refresh(scoreboardTab);
	}

	private void renderTeam()
	{
		teamTab.removeAll();
		String ownTeam = ownTeamId();
		List<String> teammates = new ArrayList<>();
		for (JsonObject member : objects(array(boardEvent, "members")))
		{
			if (!ownTeam.isEmpty() && str(member, "teamId").equals(ownTeam)) teammates.add(str(member, "displayName"));
		}
		teammates.sort(String.CASE_INSENSITIVE_ORDER);
		teamTab.add(caption(teammates.size() == 1 ? "1 member" : teammates.size() + " members"));
		teamTab.add(Box.createVerticalStrut(GAP_S));
		for (String name : teammates)
		{
			JPanel row = card();
			if (samePlayer(name, boardDisplayName)) highlightSelf(row);
			row.add(wrapped(name, TEXT, plainFont(), CARD_TEXT_W), BorderLayout.CENTER);
			teamTab.add(fitHeight(row));
			teamTab.add(Box.createVerticalStrut(LIST_GAP));
		}
		teamTab.add(Box.createVerticalStrut(GAP_L));
		JButton leave = dangerButton("Disconnect from event");
		leave.addActionListener(e -> confirmLeave());
		teamTab.add(fitHeight(leave));
		teamTab.add(Box.createVerticalStrut(GAP_S));
		teamTab.add(hint("Stops tracking on this device. Your team keeps its progress and you can rejoin with the same code."));
		refresh(teamTab);
	}

	private void confirmLeave()
	{
		if (boardEvent == null) return;
		if (confirm(this, "Disconnect from event", "Stop tracking \"" + eventName(boardEvent) + "\" on this device?\nYour team keeps its progress and you can rejoin with your team code.", "Disconnect", true))
			plugin.leaveEvent(str(boardEvent, "id"));
	}

	private void addBar(JPanel body, int value, int max, String label)
	{
		ProgressBar bar = progressBar(value, max);
		bar.setCenterLabel(label);
		body.add(Box.createVerticalStrut(GAP_S));
		body.add(bar);
		body.add(Box.createVerticalStrut(GAP_S));
	}

	private JPanel errorPanel(String heading, String body)
	{
		return emptyState(heading, body, TEXT_W - 20);
	}

	private static JLabel hint(String text)
	{
		return wrapped(text, MUTED, smallFont(), TEXT_W);
	}

	private static JLabel cardNote(String text)
	{
		return wrapped(text, MUTED, smallFont(), CARD_TEXT_W);
	}

	private static JLabel cardNoteHtml(String innerHtml)
	{
		return label(html(innerHtml, CARD_TEXT_W), MUTED, smallFont());
	}

	private void refreshPage()
	{
		refresh(page);
	}
}

package com.tsghub;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.UUID;
import java.util.function.Consumer;
import java.util.function.Supplier;
import lombok.extern.slf4j.Slf4j;

@Slf4j
final class TsgHubSignals
{
	private static final long RETRY_MILLIS = 10_000;
	private static final int MAX_BATCH = 50;

	private static final class Pending extends TsgHubOutbox.Item
	{
		final JsonObject message;
		final Set<String> deliveredTo = new HashSet<>();
		long sentAt;

		Pending(JsonObject message, long now)
		{
			super(now);
			this.message = message;
		}
	}

	private final TsgHubSocket socket;
	private final Supplier<TsgHubApi> api;
	private final Consumer<JsonObject> receiver;
	private final TsgHubOutbox<Pending> pending = new TsgHubOutbox<>();
	private final Map<String, Integer> offlineXp = new HashMap<>();

	TsgHubSignals(TsgHubSocket socket, Supplier<TsgHubApi> api, Consumer<JsonObject> receiver)
	{
		this.socket = socket;
		this.api = api;
		this.receiver = receiver;
	}

	boolean wantsChat(String message)
	{
		return matches(TsgHubRules.get().chat, message);
	}

	boolean wantsPlayers(String message)
	{
		return matches(TsgHubRules.get().players, message);
	}

	private static boolean matches(List<String> rules, String message)
	{
		for (String rule : rules) if (message.contains(rule)) return true;
		return false;
	}

	static String newId()
	{
		return UUID.randomUUID().toString();
	}

	void send(String type, JsonObject message)
	{
		message.addProperty("type", type);
		if (!message.has("id")) message.addProperty("id", newId());
		long now = System.currentTimeMillis();
		Pending entry = new Pending(message, now);
		synchronized (this)
		{
			pending.add(message.get("id").getAsString(), entry);
			if (socket.sendSignal(message)) entry.sentAt = now;
		}
	}

	void xp(String skill, int xp, int tick)
	{
		if (socket.xp(skill, xp, tick)) return;
		synchronized (this) { offlineXp.merge(skill, xp, Math::max); }
	}

	synchronized void acked(String id)
	{
		pending.remove(id);
	}

	synchronized void resend()
	{
		long now = System.currentTimeMillis();
		for (Pending entry : pending.values()) if (socket.sendSignal(entry.message)) entry.sentAt = now;
	}

	synchronized void clear()
	{
		pending.clear();
		offlineXp.clear();
	}

	void flush(Map<String, String> tokens)
	{
		long now = System.currentTimeMillis();
		List<JsonObject> xp = new ArrayList<>();
		List<Pending> entries = new ArrayList<>();
		synchronized (this)
		{
			pending.expire(now);
			if (socket.signaling())
			{
				offlineXp.clear();
				for (Pending entry : pending.values())
				{
					if (now - entry.sentAt >= RETRY_MILLIS && socket.sendSignal(entry.message)) entry.sentAt = now;
				}
				return;
			}
			if (tokens.isEmpty())
			{
				offlineXp.clear();
				return;
			}
			for (Map.Entry<String, Integer> entry : offlineXp.entrySet())
			{
				JsonObject total = new JsonObject();
				total.addProperty("type", "xp");
				total.addProperty("skill", entry.getKey());
				total.addProperty("xp", entry.getValue());
				xp.add(total);
			}
			offlineXp.clear();
			for (Pending entry : pending.values())
			{
				if (entries.size() + xp.size() >= MAX_BATCH) break;
				entries.add(entry);
			}
		}
		boolean retryXp = false;
		for (Map.Entry<String, String> event : tokens.entrySet())
		{
			List<Pending> undelivered = new ArrayList<>();
			synchronized (this) { for (Pending entry : entries) if (!entry.deliveredTo.contains(event.getKey())) undelivered.add(entry); }
			if (undelivered.isEmpty() && xp.isEmpty()) continue;
			JsonArray signals = new JsonArray();
			xp.forEach(signals::add);
			undelivered.forEach(entry -> signals.add(entry.message));
			JsonObject body = new JsonObject();
			body.add("signals", signals);
			try
			{
				JsonObject result = api.get().request("POST", "/v1/events/" + event.getKey() + "/signals", event.getValue(), body);
				delivered(undelivered, event.getKey());
				for (JsonObject message : TsgHubJson.objects(TsgHubJson.array(result, "messages"))) receiver.accept(message);
			}
			catch (TsgHubApi.HttpError e)
			{
				if (e.status == 401 || e.status == 403 || e.status == 404) delivered(undelivered, event.getKey());
				else retryXp = true;
			}
			catch (Exception e)
			{
				retryXp = true;
				log.debug("TSG Hub signal fallback failed", e);
			}
		}
		synchronized (this)
		{
			for (Pending entry : entries)
			{
				if (entry.deliveredTo.containsAll(tokens.keySet())) pending.remove(entry.message.get("id").getAsString());
			}
			if (retryXp) for (JsonObject total : xp) offlineXp.merge(total.get("skill").getAsString(), total.get("xp").getAsInt(), Math::max);
		}
	}

	private synchronized void delivered(List<Pending> entries, String eventId)
	{
		for (Pending entry : entries) entry.deliveredTo.add(eventId);
	}
}

package com.tsghub;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.Gson;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.ThreadLocalRandom;
import java.util.concurrent.TimeUnit;
import lombok.extern.slf4j.Slf4j;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.WebSocket;
import okhttp3.WebSocketListener;

@Slf4j
final class TsgHubSocket
{
	enum State { DISCONNECTED, CONNECTING, CONNECTED }

	interface Listener
	{
		void onConnection(State state);

		void onSnapshot(JsonObject message);

		void onReady(String rulesVersion);

		void onChanged(String topic, String eventId);

		void onAdminRevoked(String token);

		void onAnnouncement(String text);

		void onUpdateAvailable(String version);

		void onAck(String id);

		void onRejected(String id, int status);

		void onSubscribed();

		void onReply(JsonObject message);

		void onXpRequest(String skills);

		void onGroupHeartbeat(JsonObject message);

		void onGroupRejected(int status);
	}

	private static final int CLOSE_NORMAL = 1000;
	private static final int CLOSE_GOING_AWAY = 1001;
	private static final long PING_SECONDS = 30;
	private static final long RESTART_MIN_MILLIS = 2_000;
	private static final long RESTART_SPREAD_MILLIS = 8_000;

	private static final class Subscription
	{
		final String token;
		final boolean inClanChat;

		Subscription(String token, boolean inClanChat)
		{
			this.token = token;
			this.inClanChat = inClanChat;
		}

		@Override
		public boolean equals(Object other)
		{
			if (!(other instanceof Subscription)) return false;
			Subscription that = (Subscription) other;
			return inClanChat == that.inClanChat && token.equals(that.token);
		}

		@Override
		public int hashCode()
		{
			return Objects.hash(token, inClanChat);
		}
	}

	private final OkHttpClient http;
	private final Gson gson;
	private final HttpUrl url;
	private final ScheduledExecutorService executor;
	private final Listener listener;
	private final Map<String, Subscription> subscriptions = new HashMap<>();
	private final Map<String, String> rejectedTokens = new HashMap<>();
	private final Set<String> confirmed = new HashSet<>();
	private WebSocket socket;
	private JsonObject presence;
	private String adminToken = "";
	private Set<String> watching = new HashSet<>();
	private ScheduledFuture<?> retry;
	private String clanName = "";
	private String rejectedClan = "";
	private boolean ready;
	private final TsgHubBackoff backoff = new TsgHubBackoff(1_000, 60_000);
	private State state = State.DISCONNECTED;

	TsgHubSocket(OkHttpClient http, Gson gson, String baseUrl, ScheduledExecutorService executor, Listener listener)
	{
		this.gson = gson;
		this.http = http.newBuilder().pingInterval(PING_SECONDS, TimeUnit.SECONDS).build();
		this.url = HttpUrl.get(baseUrl.replaceAll("/+$", "") + "/v1/ws");
		this.executor = executor;
		this.listener = listener;
	}

	synchronized boolean isLive()
	{
		return ready;
	}

	synchronized void connect(String clan)
	{
		if (clan.isEmpty() || clan.equals(rejectedClan)) return;
		if (clan.equals(clanName) && (socket != null || retry != null)) return;
		close();
		clanName = clan;
		backoff.reset();
		open();
	}

	synchronized void disconnect()
	{
		close();
		clanName = "";
		rejectedClan = "";
		subscriptions.clear();
		rejectedTokens.clear();
		confirmed.clear();
		presence = null;
		adminToken = "";
		watching = new HashSet<>();
		changed();
	}

	synchronized void sync(Map<String, String> tokens, boolean inClanChat)
	{
		subscriptions.keySet().removeIf(eventId -> {
			if (tokens.containsKey(eventId)) return false;
			confirmed.remove(eventId);
			send("unsubscribe", eventId, null, false);
			return true;
		});
		for (Map.Entry<String, String> entry : tokens.entrySet())
		{
			Subscription wanted = new Subscription(entry.getValue(), inClanChat);
			if (wanted.equals(subscriptions.get(entry.getKey())) || wanted.token.equals(rejectedTokens.get(entry.getKey()))) continue;
			subscriptions.put(entry.getKey(), wanted);
			confirmed.remove(entry.getKey());
			send("subscribe", entry.getKey(), wanted.token, wanted.inClanChat);
		}
	}

	synchronized boolean presence(JsonObject payload)
	{
		boolean live = ready && socket != null;
		if (payload == null)
		{
			if (live && presence != null) socket.send("{\"type\":\"presence.leave\"}");
			presence = null;
			return live;
		}
		presence = payload;
		if (live) sendPresence();
		return live;
	}

	synchronized boolean send(String type, JsonObject body)
	{
		return emit(type, body.deepCopy());
	}

	synchronized boolean groupHeartbeat(String token, JsonObject body)
	{
		JsonObject message = body.deepCopy();
		message.addProperty("token", token);
		return emit("group.heartbeat", message);
	}

	private boolean emit(String type, JsonObject message)
	{
		if (!ready || socket == null) return false;
		message.addProperty("type", type);
		return socket.send(message.toString());
	}

	synchronized boolean signaling()
	{
		return ready && socket != null && !confirmed.isEmpty();
	}

	synchronized boolean sendSignal(JsonObject message)
	{
		return signaling() && socket.send(message.toString());
	}

	synchronized boolean xp(String skill, int xp, int tick)
	{
		if (confirmed.isEmpty()) return false;
		JsonObject message = new JsonObject();
		message.addProperty("skill", skill);
		message.addProperty("xp", xp);
		message.addProperty("tick", tick);
		return emit("xp", message);
	}

	synchronized void rewardInterface(int group, boolean open, int tick)
	{
		if (confirmed.isEmpty()) return;
		JsonObject message = new JsonObject();
		message.addProperty("group", group);
		message.addProperty("open", open);
		message.addProperty("tick", tick);
		emit("interface", message);
	}

	synchronized void watch(Set<String> topics)
	{
		if (topics.equals(watching)) return;
		watching = new HashSet<>(topics);
		if (ready && socket != null) sendWatch();
	}

	private void sendWatch()
	{
		JsonArray topics = new JsonArray();
		watching.forEach(topics::add);
		JsonObject message = new JsonObject();
		message.add("topics", topics);
		emit("watch", message);
	}

	synchronized void admin(String token)
	{
		String wanted = token == null ? "" : token;
		if (wanted.equals(adminToken)) return;
		adminToken = wanted;
		if (ready && socket != null && !adminToken.isEmpty()) sendAdmin();
	}

	private void sendAdmin()
	{
		JsonObject message = new JsonObject();
		message.addProperty("token", adminToken);
		emit("admin", message);
	}

	private void sendPresence()
	{
		emit("presence", presence.deepCopy());
	}

	private void open()
	{
		retry = null;
		Request request = new Request.Builder().url(url.newBuilder().addQueryParameter("clanName", clanName).addQueryParameter("version", TsgHubVersion.VERSION).build()).build();
		socket = http.newWebSocket(request, new Handler());
		changed();
	}

	private void close()
	{
		if (retry != null) retry.cancel(false);
		retry = null;
		if (socket != null) socket.close(CLOSE_NORMAL, null);
		socket = null;
		ready = false;
		confirmed.clear();
	}

	private void send(String type, String eventId, String token, boolean inClanChat)
	{
		JsonObject message = new JsonObject();
		message.addProperty("eventId", eventId);
		if (token != null)
		{
			message.addProperty("token", token);
			message.addProperty("inClanChat", inClanChat);
		}
		emit(type, message);
	}

	private synchronized void opened(WebSocket ws, JsonObject message)
	{
		if (ws != socket) return;
		ready = true;
		backoff.reset();
		for (Map.Entry<String, Subscription> entry : subscriptions.entrySet())
		{
			send("subscribe", entry.getKey(), entry.getValue().token, entry.getValue().inClanChat);
		}
		if (presence != null) sendPresence();
		if (!adminToken.isEmpty()) sendAdmin();
		if (!watching.isEmpty()) sendWatch();
		changed();
		String rulesVersion = TsgHubJson.str(message, "rules");
		executor.execute(() -> listener.onReady(rulesVersion));
	}

	private synchronized void rejected(WebSocket ws, String eventId)
	{
		if (ws != socket) return;
		confirmed.remove(eventId);
		Subscription subscription = subscriptions.remove(eventId);
		if (subscription != null) rejectedTokens.put(eventId, subscription.token);
	}

	private synchronized void subscribed(WebSocket ws, String eventId)
	{
		if (ws != socket || !subscriptions.containsKey(eventId)) return;
		confirmed.add(eventId);
		if (listener != null) executor.execute(listener::onSubscribed);
	}

	private synchronized void adminRevoked(WebSocket ws)
	{
		if (ws != socket || adminToken.isEmpty()) return;
		String token = adminToken;
		adminToken = "";
		executor.execute(() -> listener.onAdminRevoked(token));
	}

	private synchronized void dropped(WebSocket ws, int code, int status)
	{
		if (ws != socket) return;
		socket = null;
		ready = false;
		confirmed.clear();
		if (status == 403)
		{
			rejectedClan = clanName;
			clanName = "";
		}
		if (!clanName.isEmpty() && !executor.isShutdown())
		{
			long delay = code == CLOSE_GOING_AWAY ? restartDelay() : backoff.next();
			retry = executor.schedule(this::reopen, delay, TimeUnit.MILLISECONDS);
		}
		changed();
	}

	private void changed()
	{
		State next = ready ? State.CONNECTED : socket != null || retry != null ? State.CONNECTING : State.DISCONNECTED;
		if (next == state) return;
		state = next;
		if (listener != null && !executor.isShutdown()) executor.execute(() -> listener.onConnection(next));
	}

	private synchronized void reopen()
	{
		if (retry == null || clanName.isEmpty()) return;
		open();
	}

	private static long restartDelay()
	{
		return RESTART_MIN_MILLIS + ThreadLocalRandom.current().nextLong(RESTART_SPREAD_MILLIS);
	}

	private final class Handler extends WebSocketListener
	{
		@Override
		public void onMessage(WebSocket ws, String text)
		{
			JsonObject message;
			try
			{
				JsonElement element = gson.fromJson(text, JsonElement.class);
				if (element == null || !element.isJsonObject()) return;
				message = element.getAsJsonObject();
			}
			catch (RuntimeException e) { return; }
			String type = TsgHubJson.str(message, "type");
			String eventId = TsgHubJson.str(message, "eventId");
			switch (type)
			{
				case "ready":
					opened(ws, message);
					break;
				case "changed":
					String topic = TsgHubJson.str(message, "topic");
					dispatch(ws, () -> listener.onChanged(topic, eventId));
					break;
				case "subscribed":
					subscribed(ws, eventId);
					break;
				case "progress":
				case "claimed":
				case "notice":
					dispatch(ws, () -> listener.onReply(message));
					break;
				case "state":
					dispatch(ws, () -> listener.onSnapshot(message));
					break;
				case "group.heartbeat":
					dispatch(ws, () -> listener.onGroupHeartbeat(message));
					break;
				case "ack":
					String id = TsgHubJson.str(message, "id");
					if (!id.isEmpty()) dispatch(ws, () -> listener.onAck(id));
					break;
				case "xp.request":
					String skills = TsgHubJson.str(message, "skills");
					if (!skills.isEmpty()) dispatch(ws, () -> listener.onXpRequest(skills));
					break;
				case "admin.revoked":
					adminRevoked(ws);
					break;
				case "announcement":
					String announcement = TsgHubJson.str(message, "text");
					if (!announcement.isEmpty()) dispatch(ws, () -> listener.onAnnouncement(announcement));
					break;
				case "update":
					String version = TsgHubJson.str(message, "version");
					if (!version.isEmpty()) dispatch(ws, () -> listener.onUpdateAvailable(version));
					break;
				case "error":
					String failed = TsgHubJson.str(message, "id");
					int status = TsgHubJson.integer(message, "status", 0);
					if (!failed.isEmpty()) dispatch(ws, () -> listener.onRejected(failed, status));
					String errorTopic = TsgHubJson.str(message, "topic");
					if (!eventId.isEmpty()) rejected(ws, eventId);
					else if ("admin".equals(errorTopic) && status == 401) adminRevoked(ws);
					else if ("group".equals(errorTopic)) dispatch(ws, () -> listener.onGroupRejected(status));
					log.debug("TSG Hub socket error: {}", TsgHubJson.str(message, "message"));
					break;
				default:
			}
		}

		@Override
		public void onClosing(WebSocket ws, int code, String reason)
		{
			ws.close(CLOSE_NORMAL, null);
			dropped(ws, code, 0);
		}

		@Override
		public void onClosed(WebSocket ws, int code, String reason)
		{
			dropped(ws, code, 0);
		}

		@Override
		public void onFailure(WebSocket ws, Throwable error, Response response)
		{
			log.debug("TSG Hub socket failed", error);
			dropped(ws, 0, response == null ? 0 : response.code());
		}
	}

	private synchronized void dispatch(WebSocket ws, Runnable action)
	{
		if (ws != socket || executor.isShutdown()) return;
		executor.execute(action);
	}
}

