// Renders the plugin's panels from fixture JSON into README screenshots: ./gradlew readmeScreenshots
public class ReadmeScreenshots
{
	private static final int SCALE = 2;
	private static final int SIDEBAR_W = 242;
	private static JsonObject data;
	private static boolean sharing;
	private static File out;

	public static void main(String[] args) throws Exception
	{
		data = new JsonParser().parse(new String(Files.readAllBytes(Paths.get(args[0])), StandardCharsets.UTF_8)).getAsJsonObject();
		out = new File(args[1]);
		out.mkdirs();
		SwingUtilities.invokeAndWait(() -> {
			try
			{
				run();
			}
			catch (Exception e)
			{
				throw new RuntimeException(e);
			}
		});
		System.exit(0);
	}

	private static void run() throws Exception
	{
		RuneLiteLAF.setup();
		Instant now = Instant.parse(str("now"));
		TsgHubFormat.clock = Clock.fixed(now, ZoneOffset.UTC);
		TsgHubPlugin plugin = new TsgHubPlugin()
		{
			@Override
			String accountHash()
			{
				return "1";
			}

			@Override
			AsyncBufferedImage getItemImage(int itemId)
			{
				return itemIcon(itemId);
			}

			@Override
			AsyncBufferedImage getCoinImage(long gp)
			{
				AsyncBufferedImage icon = itemIcon(995);
				if (icon == null) return null;
				AsyncBufferedImage coins = new AsyncBufferedImage(null, icon.getWidth(), icon.getHeight(), BufferedImage.TYPE_INT_ARGB)
				{
					@Override
					public void onLoaded(Runnable runnable)
					{
						runnable.run();
					}
				};
				coins.getGraphics().drawImage(icon, 0, 0, null);
				return coins;
			}
		};
		set(plugin, "config", stub(TsgHubConfig.class));
		set(plugin, "detectedClanName", "TSGaming");
		set(plugin, "detectedClanRank", 100);
		set(plugin, "detectedPlayerName", "Crab Legs");
		set(plugin, "session", new TsgHubSession(null));
		set(plugin, "groups", new TsgHubGroups(plugin, null, (PartyService) unsafe().allocateInstance(PartyService.class), null, null, null, null));
		set(plugin, "presence", new TsgHubPresence(plugin, null, null, null, null, stopped(), null, null, null, () -> ""));
		set(plugin, "drops", new TsgHubDrops(plugin, null, null, stopped(), null, null));
		set(plugin, "announcements", new TsgHubAnnouncements(plugin, stopped(), null, () -> null, line -> { }));

		TsgHubSidebarPanel sidebar = new TsgHubSidebarPanel(plugin, new GroupMembersPanel(new GroupViewSettings() {}, null, null));

		JsonArray events = data.getAsJsonObject("eventList").getAsJsonArray("events");
		for (int i = 0; i < events.size(); i++)
		{
			JsonObject event = events.get(i).getAsJsonObject();
			String id = TsgHubJson.str(event, "id");
			event.addProperty("joined", id.equals(str("bingo")) || id.equals(str("skill")));
		}
		sidebar.setEvents(events);
		sidebar.setGroups(data.getAsJsonObject("groupsList").getAsJsonArray("groups"));
		sidebar.setMembers(data.getAsJsonObject("membersList").getAsJsonArray("members"), TsgHubJson.array(data.getAsJsonObject("membersList"), "offline"), true);
		JsonArray drops = data.getAsJsonObject("dropsList").getAsJsonArray("drops");
		for (int i = 0; i < drops.size(); i++)
		{
			JsonObject drop = drops.get(i).getAsJsonObject();
			drop.addProperty("receivedAt", now.minusSeconds(drop.remove("minutesAgo").getAsLong() * 60).toString());
		}
		sidebar.setDrops(drops);
		sidebar.showHome();
		shoot(sidebar, SIDEBAR_W, 300, "home");
		sidebar.showEventList();
		BufferedImage eventList = shoot(sidebar, SIDEBAR_W, 480, "events");

		sidebar.showBoard(data.getAsJsonObject("board").getAsJsonObject("event"), "Crab Legs", true);
		BufferedImage board = shoot(sidebar, SIDEBAR_W, 652, "board-tasks");
		selectTab(sidebar, "Scores");
		shoot(sidebar, SIDEBAR_W, 330, "board-scores");
		selectTab(sidebar, "Team");
		shoot(sidebar, SIDEBAR_W, 400, "board-team");

		sidebar.showCompetition(data.getAsJsonObject("skillBoard").getAsJsonObject("event"), "Crab Legs", true);
		shoot(sidebar, SIDEBAR_W, 400, "competition");

		sidebar.showParties();
		BufferedImage parties = shoot(sidebar, SIDEBAR_W, 480, "parties");

		sharing = true;
		sidebar.showMembers();
		shoot(sidebar, SIDEBAR_W, 400, "members");
		sidebar.showDrops();
		shoot(sidebar, SIDEBAR_W, 360, "drops");
		if (data.has("announcementsList"))
		{
			JsonArray announcements = data.getAsJsonObject("announcementsList").getAsJsonArray("announcements");
			plugin.announcements().apply(announcements);
			sidebar.setAnnouncements(TsgHubAnnouncements.published(announcements));
			sharing = false;
			sidebar.showHome();
			shoot(sidebar, SIDEBAR_W, 420, "news-home");
			sidebar.showNews();
			shoot(sidebar, SIDEBAR_W, 480, "news");
			sharing = true;
		}

		sidebar.showMembers();
		sharing = false;
		sidebar.pinCurrent();
		sidebar.showBoard(data.getAsJsonObject("board").getAsJsonObject("event"), "Crab Legs", true);
		selectTab(sidebar, "Tasks");
		shoot(sidebar, SIDEBAR_W, 680, "dock");

		TsgHubPanel organizer = new TsgHubPanel(plugin);
		organizer.setManagedEvents(data.getAsJsonObject("managed").getAsJsonArray("events"));
		organizer.openOrganizerEvent(data.getAsJsonObject("organizer"));
		shoot(organizer, 860, 300, "admin-teams");
		selectTab(organizer, "Tasks");
		shoot(organizer, 860, 580, "admin-tasks");
		if (data.has("announcementsList"))
		{
			JsonArray announcements = data.getAsJsonObject("announcementsList").getAsJsonArray("announcements");
			TsgHubNewsEditor news = new TsgHubNewsEditor(plugin);
			news.setAnnouncements(announcements);
			TsgHubAdminWindow window = new TsgHubAdminWindow(organizer, () -> { }, news, () -> { }, new TsgHubActivityPanel(null, () -> 14), () -> { });
			shoot(window, 860, 340, "admin-events");
			selectTab(window, "Announcements");
			news.showAnnouncement(TsgHubJson.str(announcements.get(0).getAsJsonObject(), "id"));
			shoot(window, 860, 560, "admin-news");
			((AbstractButton) find(window, "Edit", AbstractButton.class)).doClick();
			shoot(window, 860, 560, "admin-news-edit");
			((AbstractButton) find(window, "New announcement", AbstractButton.class)).doClick();
			shoot(window, 860, 560, "admin-news-form");
		}

		hero(480, eventList, board, parties);
	}

	private static String str(String key)
	{
		return data.get(key).getAsString();
	}

	// Sidebar shots side by side, cropped to one height.
	private static void hero(int height, BufferedImage... shots) throws Exception
	{
		int gap = 24;
		int width = gap;
		for (BufferedImage shot : shots) width += shot.getWidth() / SCALE + gap;
		BufferedImage image = new BufferedImage(width * SCALE, (height + gap * 2) * SCALE, BufferedImage.TYPE_INT_RGB);
		Graphics2D g = image.createGraphics();
		g.setColor(new java.awt.Color(0x1b1b1b));
		g.fillRect(0, 0, image.getWidth(), image.getHeight());
		int x = gap * SCALE;
		for (BufferedImage shot : shots)
		{
			g.drawImage(shot.getSubimage(0, 0, shot.getWidth(), height * SCALE), x, gap * SCALE, null);
			x += shot.getWidth() + gap * SCALE;
		}
		g.dispose();
		ImageIO.write(image, "png", new File(out, "hero.png"));
	}

	private static BufferedImage shoot(JComponent panel, int width, int height, String name) throws Exception
	{
		JFrame frame = new JFrame();
		frame.setUndecorated(true);
		frame.setContentPane(panel);
		panel.setPreferredSize(new Dimension(width, height));
		frame.pack();
		// Container.paintComponents skips hidden windows, so show it (transparent, off screen).
		frame.setOpacity(0f);
		frame.setLocation(-4000, -4000);
		frame.setVisible(true);
		for (int i = 0; i < 3; i++)
		{
			invalidateAll(panel);
			frame.validate();
		}
		BufferedImage image = new BufferedImage(width * SCALE, height * SCALE, BufferedImage.TYPE_INT_RGB);
		Graphics2D g = image.createGraphics();
		g.scale(SCALE, SCALE);
		panel.paint(g);
		g.dispose();
		ImageIO.write(image, "png", new File(out, name + ".png"));
		frame.setContentPane(new JComponent() {});
		frame.dispose();
		return image;
	}

	private static void invalidateAll(Component c)
	{
		c.invalidate();
		if (c instanceof Container) for (Component child : ((Container) c).getComponents()) invalidateAll(child);
	}

	private static sun.misc.Unsafe unsafe() throws Exception
	{
		Field f = sun.misc.Unsafe.class.getDeclaredField("theUnsafe");
		f.setAccessible(true);
		return (sun.misc.Unsafe) f.get(null);
	}

	private static void selectTab(Container root, String text)
	{
		Component tab = find(root, text, MaterialTab.class);
		if (tab == null) throw new IllegalStateException("No tab " + text);
		((MaterialTabGroup) tab.getParent()).select((MaterialTab) tab);
	}

	private static Component find(Container root, String text, Class<?> type)
	{
		for (Component c : root.getComponents())
		{
			if (type.isInstance(c))
			{
				String label = c instanceof MaterialTab ? ((MaterialTab) c).getText() : ((AbstractButton) c).getText();
				if (label != null && label.startsWith(text)) return c;
			}
			if (c instanceof Container)
			{
				Component found = find((Container) c, text, type);
				if (found != null) return found;
			}
		}
		return null;
	}

	private static java.util.concurrent.ScheduledExecutorService stopped()
	{
		java.util.concurrent.ScheduledExecutorService executor = java.util.concurrent.Executors.newSingleThreadScheduledExecutor();
		executor.shutdown();
		return executor;
	}

	// Interface stub returning false, 0 or null, with sharing on once enabled.
	@SuppressWarnings("unchecked")
	private static <T> T stub(Class<T> type)
	{
		return (T) Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[]{type}, (proxy, method, args) -> {
			Class<?> r = method.getReturnType();
			if (r == boolean.class) return sharing && (method.getName().equals("dataSharingOptIn") || method.getName().equals("shareLocation"));
			if (r == int.class) return 0;
			if (r == long.class) return 0L;
			return null;
		});
	}

	// Item icons come from RuneLite's static cache, since there's no ItemManager here.
	private static AsyncBufferedImage itemIcon(int itemId)
	{
		try
		{
			BufferedImage icon = ImageIO.read(new java.net.URL("https://static.runelite.net/cache/item/icon/" + itemId + ".png"));
			if (icon == null) return null;
			AsyncBufferedImage image = new AsyncBufferedImage(null, icon.getWidth(), icon.getHeight(), BufferedImage.TYPE_INT_ARGB);
			Graphics2D g = image.createGraphics();
			g.drawImage(icon, 0, 0, null);
			g.dispose();
			image.loaded();
			return image;
		}
		catch (java.io.IOException e)
		{
			return null;
		}
	}

	private static void set(Object target, String field, Object value) throws Exception
	{
		Class<?> type = target.getClass();
		while (type.getSuperclass() != null && java.util.Arrays.stream(type.getDeclaredFields()).noneMatch(f -> f.getName().equals(field))) type = type.getSuperclass();
		Field f = type.getDeclaredField(field);
		f.setAccessible(true);
		f.set(target, value);
	}
}

package com.tsghub;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

public class ReportsTest
{
	private final List<JsonObject> socketSent = new ArrayList<>();
	private final List<JsonObject> posted = new ArrayList<>();
	private boolean live = true;
	private int status = 200;
	private long now = 1_000;

	private TsgHubReports reports()
	{
		return new TsgHubReports((type, body) -> {
			if (!live) return false;
			JsonObject message = body.deepCopy();
			message.addProperty("type", type);
			socketSent.add(message);
			return true;
		}, (path, body) -> {
			posted.add(body.deepCopy());
			if (status == -1) throw new IOException("offline");
			if (status != 200) throw new TsgHubApi.HttpError(status, "HTTP " + status);
		}, () -> now);
	}

	private static JsonObject drop()
	{
		JsonObject body = new JsonObject();
		body.addProperty("message", "Bob received a drop: Abyssal whip");
		return body;
	}

	@Test
	public void ackRemovesPending()
	{
		TsgHubReports reports = reports();
		assertTrue(reports.send("drop", "/v1/drops", drop()));
		String id = socketSent.get(0).get("id").getAsString();
		assertEquals("drop", socketSent.get(0).get("type").getAsString());
		reports.acked(id);
		assertEquals(0, reports.size());
		now += TsgHubReports.RETRY_MILLIS;
		reports.flush();
		assertTrue(posted.isEmpty());
	}

	@Test
	public void unackedFallsBackToRestWithSameId()
	{
		TsgHubReports reports = reports();
		reports.send("drop", "/v1/drops", drop());
		String id = socketSent.get(0).get("id").getAsString();
		reports.flush();
		assertTrue(posted.isEmpty());

		now += TsgHubReports.RETRY_MILLIS;
		reports.flush();
		assertEquals(1, posted.size());
		assertEquals(id, posted.get(0).get("id").getAsString());
		assertFalse(posted.get(0).has("type"));
		assertEquals(0, reports.size());
	}

	@Test
	public void offlineSocketPostsImmediately()
	{
		live = false;
		TsgHubReports reports = reports();
		assertFalse(reports.send("group", "/v1/group-content", drop()));
		reports.flush();
		assertEquals(1, posted.size());
		assertEquals(0, reports.size());
	}

	@Test
	public void finalErrorDrops()
	{
		TsgHubReports reports = reports();
		reports.send("drop", "/v1/drops", drop());
		reports.failed(socketSent.get(0).get("id").getAsString(), 400);
		assertEquals(0, reports.size());

		live = false;
		status = 403;
		reports.send("drop", "/v1/drops", drop());
		reports.flush();
		assertEquals(0, reports.size());
	}

	@Test
	public void rateLimitAndServerErrorsRetry()
	{
		TsgHubReports reports = reports();
		reports.send("drop", "/v1/drops", drop());
		String id = socketSent.get(0).get("id").getAsString();
		reports.failed(id, 429);
		assertEquals(1, reports.size());

		now += TsgHubReports.RETRY_MILLIS;
		status = 429;
		reports.flush();
		assertEquals(1, reports.size());
		status = 500;
		reports.flush();
		assertEquals(1, posted.size());
		now += TsgHubReports.RETRY_MILLIS;
		reports.flush();
		assertEquals(1, reports.size());
		status = -1;
		now += TsgHubReports.RETRY_MILLIS;
		reports.flush();
		assertEquals(1, reports.size());

		status = 200;
		now += TsgHubReports.RETRY_MILLIS;
		reports.flush();
		assertEquals(0, reports.size());
		assertTrue(posted.stream().allMatch(body -> id.equals(body.get("id").getAsString())));
	}

	@Test
	public void networkFailureStopsFlush()
	{
		live = false;
		status = -1;
		TsgHubReports reports = reports();
		reports.send("drop", "/v1/drops", drop());
		reports.send("drop", "/v1/drops", drop());
		reports.flush();
		assertEquals(1, posted.size());
		assertEquals(2, reports.size());
	}

	@Test
	public void reconnectResendsOverSocket()
	{
		live = false;
		status = 500;
		TsgHubReports reports = reports();
		reports.send("drop", "/v1/drops", drop());
		reports.flush();
		live = true;
		reports.resend();
		assertEquals(1, socketSent.size());
		assertEquals(posted.get(0).get("id"), socketSent.get(0).get("id"));
	}

	@Test
	public void expiresAfterMaxAge()
	{
		live = false;
		status = 500;
		TsgHubReports reports = reports();
		reports.send("drop", "/v1/drops", drop());
		now += TsgHubOutbox.MAX_AGE_MILLIS + 1;
		reports.flush();
		assertEquals(0, reports.size());
		assertTrue(posted.isEmpty());
	}

	@Test
	public void capsPending()
	{
		TsgHubReports reports = reports();
		for (int i = 0; i < TsgHubOutbox.MAX_PENDING + 5; i++) reports.send("drop", "/v1/drops", drop());
		assertEquals(TsgHubOutbox.MAX_PENDING, reports.size());
		reports.acked(socketSent.get(0).get("id").getAsString());
		assertEquals(TsgHubOutbox.MAX_PENDING, reports.size());
		reports.acked(socketSent.get(socketSent.size() - 1).get("id").getAsString());
		assertEquals(TsgHubOutbox.MAX_PENDING - 1, reports.size());
	}
}

package com.tsghub;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import net.runelite.client.util.Filepath;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Protocol;
import okhttp3.Response;
import okhttp3.ResponseBody;
import okio.Buffer;
import org.junit.After;
import org.junit.BeforeClass;
import org.junit.Test;

public class SignalsTest
{
	@BeforeClass
	public static void rules()
	{
		TsgHubRules.loadBundled(new Gson());
	}

	private final ScheduledExecutorService executor = Executors.newSingleThreadScheduledExecutor();
	private final List<JsonObject> posted = new ArrayList<>();
	private final List<JsonObject> received = new ArrayList<>();
	private final List<String> paths = new ArrayList<>();
	private final Map<String, Integer> eventStatus = new HashMap<>();
	private int status = 200;

	@After
	public void stop()
	{
		executor.shutdownNow();
	}

	private TsgHubSignals signals()
	{
		OkHttpClient http = new OkHttpClient.Builder().addInterceptor(chain -> {
			Buffer body = new Buffer();
			chain.request().body().writeTo(body);
			posted.add(new JsonParser().parse(body.readUtf8()).getAsJsonObject());
			String path = chain.request().url().encodedPath();
			paths.add(path);
			int code = eventStatus.getOrDefault(path, status);
			String reply = "{\"acked\":[],\"messages\":[{\"type\":\"claimed\",\"taskTitle\":\"Hydra\",\"progress\":\"1/3\"}]}";
			return new Response.Builder().request(chain.request()).protocol(Protocol.HTTP_1_1).code(code).message("")
				.body(ResponseBody.create(MediaType.get("application/json"), reply)).build();
		}).build();
		TsgHubSocket socket = new TsgHubSocket(http, new Gson(), "https://hub.test", executor, null);
		TsgHubApi api = new TsgHubApi(http, new Gson(), "https://hub.test");
		return new TsgHubSignals(socket, () -> api, received::add);
	}

	@Test
	public void serverRulesReplaceBundled() throws Exception
	{
		TsgHubSignals signals = signals();
		TsgHubRules bundled = TsgHubRules.get();
		assertEquals("Alchemical Hydra", AreaNames.forRegion(5536).name);
		assertEquals("Vorkath", ActivityDetector.bossFor("Vorkath"));
		assertTrue(bundled.pets.contains(11995));
		assertTrue(bundled.rewardInterfaces.contains(153));
		assertTrue(signals.wantsChat("your vorkath kill count is: 5."));
		assertFalse(signals.wantsChat("you catch a shrimp."));
		assertTrue(signals.wantsPlayers("theatre of blood completion time: 20:00"));

		JsonObject server = new JsonParser().parse("{\"version\":\"abc\",\"chat\":[\"You catch\"],\"areas\":[{\"type\":\"CITIES\",\"name\":\"Lumbridge\",\"regions\":[5536]}]}").getAsJsonObject();
		try
		{
			TsgHubRules.apply(server);
			assertEquals("abc", TsgHubRules.get().version);
			assertTrue(signals.wantsChat("you catch a shrimp."));
			assertEquals("Lumbridge", AreaNames.forRegion(5536).name);
			assertNull(ActivityDetector.bossFor("Vorkath"));
		}
		finally { restoreBundled(); }
	}

	@Test
	public void socketSendFallsBackWhenNotReady()
	{
		TsgHubSocket socket = new TsgHubSocket(new OkHttpClient(), new Gson(), "https://hub.test", executor, null);
		JsonObject body = new JsonObject();
		body.addProperty("message", "Bob received a drop: Abyssal whip");
		assertFalse(socket.send("drop", body));
		assertFalse(body.has("type"));
	}

	@Test
	public void cachedRulesSurviveRestart() throws Exception
	{
		Filepath cache = Filepath.Unchecked.getRooted(Files.createTempDirectory("tsghub")).join("rules.json");
		JsonObject server = new JsonParser().parse("{\"version\":\"v2\",\"chat\":[\"you catch\"]}").getAsJsonObject();
		try
		{
			TsgHubRules.save(server, cache);
			restoreBundled();
			assertEquals("", TsgHubRules.get().version);
			TsgHubRules.loadCached(cache, new Gson());
			assertEquals("v2", TsgHubRules.get().version);
			assertTrue(TsgHubRules.get().chat.contains("you catch"));
		}
		finally { restoreBundled(); }
	}

	private static void restoreBundled() throws Exception
	{
		try (InputStreamReader reader = new InputStreamReader(TsgHubRules.class.getResourceAsStream("rules.json"), StandardCharsets.UTF_8))
		{
			TsgHubRules.apply(new JsonParser().parse(reader).getAsJsonObject());
		}
	}

	@Test
	public void fallbackRetriesOnlyEventsThatFailed()
	{
		TsgHubSignals signals = signals();
		signals.send("loot", new JsonObject());
		Map<String, String> tokens = new LinkedHashMap<>();
		tokens.put("e1", "member");
		tokens.put("e2", "member");
		tokens.put("gone", "member");
		eventStatus.put("/v1/events/e2/signals", 500);
		eventStatus.put("/v1/events/gone/signals", 404);
		signals.flush(tokens);
		assertEquals(3, posted.size());

		eventStatus.remove("/v1/events/e2/signals");
		signals.flush(tokens);
		assertEquals(List.of("/v1/events/e1/signals", "/v1/events/e2/signals", "/v1/events/gone/signals", "/v1/events/e2/signals"), paths);

		signals.flush(tokens);
		assertEquals(4, posted.size());
	}

	@Test
	public void cacheFromAnotherPluginVersionIsIgnored() throws Exception
	{
		Filepath cache = Filepath.Unchecked.getRooted(Files.createTempDirectory("tsghub")).join("rules.json");
		cache.write("{\"plugin\":\"0.0.1\",\"rules\":{\"version\":\"old\"}}");
		try
		{
			TsgHubRules.loadCached(cache, new Gson());
			assertEquals("", TsgHubRules.get().version);
			assertTrue(TsgHubRules.get().petMessages.contains("you feel something weird sneaking into your backpack"));
		}
		finally { restoreBundled(); }
	}

	@Test
	public void fallbackPostsPendingAndClearsOnSuccess()
	{
		TsgHubSignals signals = signals();
		JsonObject loot = new JsonObject();
		loot.addProperty("sourceName", "Alchemical Hydra");
		signals.send("loot", loot);
		signals.xp("WOODCUTTING", 1000, 1);
		signals.xp("WOODCUTTING", 1200, 2);

		status = 500;
		signals.flush(Map.of("e1", "member"));
		assertEquals(1, posted.size());
		assertEquals(2, posted.get(0).getAsJsonArray("signals").size());

		status = 200;
		signals.flush(Map.of("e1", "member"));
		assertEquals(2, posted.size());
		JsonObject retried = posted.get(1).getAsJsonArray("signals").get(0).getAsJsonObject();
		assertEquals(1200, retried.get("xp").getAsInt());
		assertEquals(1, received.size());

		signals.flush(Map.of("e1", "member"));
		assertEquals(2, posted.size());
	}
}

